/// One Checker-authorized Set payload, bound to its exact MIR instruction,
/// value identity, and both Checker/MIR structural type identities.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct OrdinaryMapOwnedAnyV2PayloadSelectionEntry {
    pub owner: NodeId,
    pub instruction: super::MirInstructionId,
    pub value: super::MirValueId,
    pub checker_type: crate::core::ir::ResolvedTypeId,
    pub mir_type: crate::core::ir::ResolvedTypeId,
    pub type_desc_digest: String,
}

/// A unique TypeDesc admitted as an ordinary Map/Any owner-v2 payload.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct OrdinaryMapOwnedAnyV2SelectedType {
    pub type_id: crate::core::ir::ResolvedTypeId,
    pub type_desc_digest: String,
}

/// Why one exact TypeDesc is accepted as the target of an AnyOwner-v2
/// unpack. A Set-selected payload is scoped to the GetAny root lineage;
/// otherwise only the canonical Copy i32 miss token may authorize an unpack.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum OrdinaryMapOwnedAnyV2UnpackPayloadSource {
    SelectedSetPayload,
    CanonicalI32Miss,
}

/// Core-owned, deterministic proof of the payload TypeDesc set selected by
/// Checker receipts for ordinary Map/Any owner-v2 Set actions.
///
/// Consumers may use `selected_types` as the closed selection table, but it
/// grants no other Map operation or route readiness by itself. `entries`
/// bind each selected type back to its Checker action and exact MIR Set value.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OrdinaryMapOwnedAnyV2PayloadSelectionReceipt {
    pub schema: &'static str,
    pub profile: &'static str,
    pub mir_digest: String,
    pub type_desc_digest: String,
    pub entries: Vec<OrdinaryMapOwnedAnyV2PayloadSelectionEntry>,
    pub selected_types: Vec<OrdinaryMapOwnedAnyV2SelectedType>,
    pub selection_digest: String,
}

/// Derived Core proof for one ordinary Map/Any V2 GetAny result. It joins
/// the private Checker action/result receipts to the dedicated MIR GetAny,
/// direct binding Move, explicit Drop, and the canonical miss payload TypeDesc.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct OrdinaryMapOwnedAnyV2GetAnyResultReceipt {
    pub schema: &'static str,
    pub profile: &'static str,
    pub owner: NodeId,
    pub operation: NodeId,
    pub instruction: super::MirInstructionId,
    pub source_node: NodeId,
    pub source_local: crate::core::ir::ResolvedLocalId,
    pub root: super::MirValueId,
    pub checker_source_type: crate::core::ir::ResolvedTypeId,
    pub key_node: NodeId,
    pub key: super::MirValueId,
    pub checker_key_type: crate::core::ir::ResolvedTypeId,
    pub checker_key_local: Option<crate::core::ir::ResolvedLocalId>,
    /// Checker binding mutability for a direct-local key. It is absent for
    /// expression keys and copied into the result receipt so narrow routes
    /// can prove the key cannot be rebound between Set and GetAny.
    pub checker_key_local_mutable: Option<bool>,
    /// Present only when Checker statically evaluated the exact String key.
    pub checker_key_static_digest: Option<String>,
    pub checker_result_type: crate::core::ir::ResolvedTypeId,
    pub result: super::MirValueId,
    pub mir_result_type: crate::core::ir::ResolvedTypeId,
    pub binding_local: crate::core::ir::ResolvedLocalId,
    pub binding: super::MirValueId,
    pub binding_point: NodeId,
    pub(crate) settlement: crate::core::OrdinaryMapOwnedAnyV2ResultSettlementKind,
    pub settlement_point: NodeId,
    pub settlement_instruction: super::MirInstructionId,
    /// Present only for the directly nested `map_get(map_new(), key)` shape.
    /// This is the Checker-owned root identity plus exact MIR construction,
    /// GetAny, and immediate root-Drop sites.
    pub temporary_root: Option<OrdinaryMapOwnedAnyV2TemporaryRootMirReceipt>,
    pub miss_payload_type: crate::core::ir::ResolvedTypeId,
    pub miss_payload_type_desc_digest: String,
}

/// Exact typed MIR binding for one Checker-proved canonical
/// `std::maps.get_or_default<i32>` callsite. The three argument values retain
/// their source order and the root's synthetic MIR TypeDesc is explicit, so
/// AST-free consumers never infer the borrowed root or i32 ABI from a raw
/// handle. The private Checker witness is re-derived from the caller's
/// ownership receipt on every validation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OrdinaryMapOwnedAnyV2GetOrDefaultI32MirReceipt {
    pub schema: &'static str,
    pub profile: &'static str,
    checker: crate::core::ownership::OrdinaryMapOwnedAnyV2GetOrDefaultI32Receipt,
    pub owner: NodeId,
    pub callsite: NodeId,
    pub call_target: NodeId,
    pub instruction: super::MirInstructionId,
    pub argument_order: [NodeId; 3],
    /// Formal helper parameters in the same order as `argument_order`.
    /// Position zero proves that the caller's live Map root is the canonical
    /// helper's View parameter rather than a raw handle move.
    pub call_parameter_order: [crate::core::ir::ResolvedParameterId; 3],
    pub caller_root_argument: NodeId,
    pub caller_initial_root_local: crate::core::ir::ResolvedLocalId,
    pub caller_root_local: crate::core::ir::ResolvedLocalId,
    pub caller_result_local: crate::core::ir::ResolvedLocalId,
    pub caller_call_binding_point: NodeId,
    pub caller_initial_root_drop_point: NodeId,
    pub caller_root_drop_point: NodeId,
    pub caller_initial_root_drop_instruction: super::MirInstructionId,
    pub caller_root_drop_instruction: super::MirInstructionId,
    pub helper_map_parameter: crate::core::ir::ResolvedParameterId,
    pub helper_map_permission: crate::core::Permission,
    pub helper_key_parameter: crate::core::ir::ResolvedParameterId,
    pub helper_default_parameter: crate::core::ir::ResolvedParameterId,
    pub helper_pair_binding_point: NodeId,
    pub helper_found_condition: NodeId,
    pub helper_found_arm_block: NodeId,
    pub helper_default_arm_block: NodeId,
    pub helper_payload_projection: NodeId,
    pub helper_unpack_cast: NodeId,
    pub helper_selected_binding_point: NodeId,
    pub helper_selected_local: crate::core::ir::ResolvedLocalId,
    pub helper_default_load: NodeId,
    pub helper_pair_drop_point: NodeId,
    pub helper_return_node: NodeId,
    pub type_argument: crate::core::ir::ResolvedTypeId,
    pub result: super::MirValueId,
    pub root: super::MirValueId,
    pub key: super::MirValueId,
    pub default: super::MirValueId,
    pub root_type: crate::core::ir::ResolvedTypeId,
    pub key_type: crate::core::ir::ResolvedTypeId,
    pub default_type: crate::core::ir::ResolvedTypeId,
    pub result_type: crate::core::ir::ResolvedTypeId,
    /// Canonical MIR TypeDesc identities used by the fused implementation.
    /// The caller's source key/default/result identities remain exposed above;
    /// these fields bind the opaque V2 GetAny owner and tuple ABI that the
    /// specialized operation must check and settle.
    pub root_type_desc: crate::core::ir::ResolvedTypeId,
    pub key_type_desc: crate::core::ir::ResolvedTypeId,
    pub default_type_desc: crate::core::ir::ResolvedTypeId,
    pub result_type_desc: crate::core::ir::ResolvedTypeId,
    pub pair_type_desc: crate::core::ir::ResolvedTypeId,
    pub payload_owner_type_desc: crate::core::ir::ResolvedTypeId,
    pub selected_payload_type_desc: crate::core::ir::ResolvedTypeId,
}

impl OrdinaryMapOwnedAnyV2GetOrDefaultI32MirReceipt {
    pub(crate) fn checker_caller_root_type(&self) -> &crate::core::ir::ResolvedTypeId {
        &self.checker.caller_root_type
    }

    pub fn validate(&self) -> Result<(), String> {
        let checker = &self.checker;
        if checker.call_arguments.len() != 3
            || checker.call_argument_types.len() != 3
            || checker.call_parameters.len() != 3
            || checker.call_conversions.len() != 3
        {
            return Err("GetOrDefault<i32> Checker receipt has an invalid argument shape".into());
        }
        let expected_instruction = super::MirInstructionId::new(format!(
            "inst:ordinary_map_owned_any_v2_get_or_default_i32:{}",
            checker.call_node.0
        ))
        .map_err(|error| error.to_string())?;
        let expected_result = super::MirValueId::new(format!("expr:{}", checker.call_node.0))
            .map_err(|error| error.to_string())?;
        let expected_root =
            super::MirValueId::new(format!("local:{}", checker.caller_root_local.0 .0))
                .map_err(|error| error.to_string())?;
        let expected_key = super::MirValueId::new(format!("expr:{}", checker.caller_query_key.0))
            .map_err(|error| error.to_string())?;
        let expected_default = super::MirValueId::new(format!("expr:{}", checker.caller_default.0))
            .map_err(|error| error.to_string())?;
        let expected_initial_root =
            super::MirValueId::new(format!("local:{}", checker.caller_initial_root_local.0 .0))
                .map_err(|error| error.to_string())?;
        let expected_initial_drop = super::MirInstructionId::new(format!(
            "inst:ordinary_map_owned_any_v2_drop:{expected_initial_root}:{}",
            checker.caller_initial_root_drop_point.0
        ))
        .map_err(|error| error.to_string())?;
        let expected_root_drop = super::MirInstructionId::new(format!(
            "inst:ordinary_map_owned_any_v2_drop:{expected_root}:{}",
            checker.caller_root_drop_point.0
        ))
        .map_err(|error| error.to_string())?;
        if self.schema != ORDINARY_MAP_OWNED_ANY_V2_GET_OR_DEFAULT_I32_SCHEMA
            || self.profile != ORDINARY_MAP_OWNED_ANY_V2_GET_OR_DEFAULT_I32_PROFILE
            || checker.profile_version.canonical_text() != self.profile
            || self.owner != checker.caller_owner
            || self.callsite != checker.call_node
            || self.call_target != checker.call_target
            || self.instruction != expected_instruction
            || self.argument_order != checker.call_arguments.as_slice()
            || self.call_parameter_order.as_slice() != checker.call_parameters.as_slice()
            || self.caller_root_argument != checker.call_arguments[0]
            || self.caller_initial_root_local != checker.caller_initial_root_local
            || self.caller_root_local != checker.caller_root_local
            || self.caller_result_local != checker.caller_result_local
            || self.caller_call_binding_point != checker.caller_call_binding_point
            || self.caller_initial_root_drop_point != checker.caller_initial_root_drop_point
            || self.caller_root_drop_point != checker.caller_root_drop_point
            || self.caller_initial_root_drop_instruction != expected_initial_drop
            || self.caller_root_drop_instruction != expected_root_drop
            || self.helper_map_parameter != checker.helper_map_parameter
            || self.helper_map_permission != checker.helper_map_permission
            || self.helper_map_permission != crate::core::Permission::View
            || self.helper_key_parameter != checker.helper_key_parameter
            || self.helper_default_parameter != checker.helper_default_parameter
            || self.helper_pair_binding_point != checker.helper_pair_binding_point
            || self.helper_found_condition != checker.helper_found_condition
            || self.helper_found_arm_block != checker.helper_found_arm_block
            || self.helper_default_arm_block != checker.helper_default_arm_block
            || self.helper_payload_projection != checker.helper_payload_projection
            || self.helper_unpack_cast != checker.helper_unpack_cast
            || self.helper_selected_binding_point != checker.helper_selected_binding_point
            || self.helper_selected_local != checker.helper_selected_local
            || self.helper_default_load != checker.helper_default_load
            || self.helper_pair_drop_point != checker.helper_pair_drop_point
            || self.helper_return_node != checker.helper_return_node
            || self.type_argument != checker.call_type_argument
            || self.result != expected_result
            || self.root != expected_root
            || self.key != expected_key
            || self.default != expected_default
            || self.key_type != checker.call_argument_types[1]
            || self.default_type != checker.call_argument_types[2]
            || self.result_type != checker.call_result_type
            || self.default_type != self.type_argument
            || self.result_type != self.type_argument
            || self.root_type != super::types::ordinary_map_owned_any_v2_type_id()
            || self.root_type_desc != self.root_type
            || self.key_type_desc != self.key_type
            || self.default_type_desc != self.default_type
            || self.result_type_desc != self.result_type
            || self.pair_type_desc != super::types::ordinary_map_owned_any_v2_get_result_type_id()
            || self.payload_owner_type_desc
                != super::types::ordinary_map_owned_any_v2_payload_type_id()
            || self.selected_payload_type_desc != self.type_argument
        {
            return Err("GetOrDefault<i32> MIR receipt disagrees with its exact Checker caller/callsite binding".into());
        }
        if self.caller_initial_root_local == self.caller_root_local
            || self.caller_initial_root_drop_point == self.caller_root_drop_point
            || self.caller_initial_root_drop_point == self.caller_call_binding_point
            || self.caller_root_drop_point == self.caller_call_binding_point
        {
            return Err(
                "GetOrDefault<i32> caller root lineage or explicit settlements are not distinct"
                    .into(),
            );
        }
        Ok(())
    }

    pub fn validate_against_program(&self, program: &MirProgram) -> Result<(), String> {
        self.validate()?;
        if program
            .actor_execution_plan()
            .is_some_and(|plan| plan.tagged_functions.contains(&self.owner))
        {
            return Err(
                "GetOrDefault<i32> caller is Actor-tagged and cannot use this ordinary callable route".into(),
            );
        }
        let derived = program.ordinary_map_owned_any_v2_get_or_default_i32_receipts()?;
        if derived.as_slice() != [self.clone()] {
            return Err("GetOrDefault<i32> MIR receipt differs from the uniquely derived whole-program witness".into());
        }
        if program.functions().contains_key(&self.call_target)
            || program
                .instances()
                .values()
                .any(|instance| instance.template == self.call_target)
            || program.functions().values().any(|function| {
                function.blocks.values().any(|block| {
                    block.instructions.iter().any(|instruction| {
                        matches!(
                            &instruction.kind,
                            super::MirInstructionKind::Call {
                                callee: crate::core::ir::ResolvedCallee::Function(target),
                                ..
                            } if target == &self.call_target
                        )
                    })
                })
            })
        {
            return Err(
                "GetOrDefault<i32> generic helper leaked into executable MIR or retained a generic Call fallback".into(),
            );
        }
        let catalog = program.type_catalog();
        for (role, descriptor) in [
            ("root", &self.root_type_desc),
            ("key", &self.key_type_desc),
            ("default", &self.default_type_desc),
            ("result", &self.result_type_desc),
            ("pair", &self.pair_type_desc),
            ("payload owner", &self.payload_owner_type_desc),
            ("selected payload", &self.selected_payload_type_desc),
        ] {
            if catalog.get(descriptor).is_none() {
                return Err(format!(
                    "GetOrDefault<i32> MIR receipt references missing {role} TypeDesc '{}'",
                    descriptor.as_str()
                ));
            }
        }
        Ok(())
    }

    /// Rebind this witness to the live CheckedProgram that authorized the MIR
    /// graph. This keeps native/CLI route selection from trusting a detached
    /// MIR-owned copy of the Checker receipt.
    pub(crate) fn validate_against_checked_program(
        &self,
        checked: &crate::core::CheckedProgram,
    ) -> Result<(), String> {
        self.validate()?;
        let receipts = checked
            .resource_analyses()
            .values()
            .filter_map(|analysis| {
                analysis
                    .ordinary_map_owned_any_v2_cfg_receipt
                    .as_ref()?
                    .get_or_default_i32_receipt
                    .as_ref()
            })
            .collect::<Vec<_>>();
        let [checker] = receipts.as_slice() else {
            return Err(format!(
                "GetOrDefault<i32> route requires exactly one CheckedProgram receipt, observed {}",
                receipts.len()
            ));
        };
        if *checker != &self.checker {
            return Err(
                "GetOrDefault<i32> MIR receipt differs from the live CheckedProgram witness".into(),
            );
        }
        Ok(())
    }
}

