impl OrdinaryMapOwnedAnyV2GetOrDefaultStringMirReceipt {
    pub(crate) fn checker_caller_root_type(&self) -> &crate::core::ir::ResolvedTypeId {
        &self.checker.caller_root_type
    }

    pub fn validate(&self) -> Result<(), String> {
        let checker = &self.checker;
        if checker.call_arguments.len() != 3
            || checker.call_argument_types.len() != 3
            || checker.call_parameters.len() != 3
            || checker.call_conversions.len() != 3
        {
            return Err(
                "GetOrDefault<String> Checker receipt has an invalid argument shape".into(),
            );
        }
        let expected_instruction = super::MirInstructionId::new(format!(
            "inst:ordinary_map_owned_any_v2_get_or_default_string:{}",
            checker.call_node.0
        ))
        .map_err(|error| error.to_string())?;
        let expected_result = super::MirValueId::new(format!("expr:{}", checker.call_node.0))
            .map_err(|error| error.to_string())?;
        let expected_root =
            super::MirValueId::new(format!("local:{}", checker.caller_root_local.0 .0))
                .map_err(|error| error.to_string())?;
        let expected_key = super::MirValueId::new(format!("expr:{}", checker.caller_query_key.0))
            .map_err(|error| error.to_string())?;
        let expected_default = super::MirValueId::new(format!("expr:{}", checker.caller_default.0))
            .map_err(|error| error.to_string())?;
        let expected_initial_root =
            super::MirValueId::new(format!("local:{}", checker.caller_initial_root_local.0 .0))
                .map_err(|error| error.to_string())?;
        let expected_initial_drop = super::MirInstructionId::new(format!(
            "inst:ordinary_map_owned_any_v2_drop:{expected_initial_root}:{}",
            checker.caller_initial_root_drop_point.0
        ))
        .map_err(|error| error.to_string())?;
        let expected_root_drop = super::MirInstructionId::new(format!(
            "inst:ordinary_map_owned_any_v2_drop:{expected_root}:{}",
            checker.caller_root_drop_point.0
        ))
        .map_err(|error| error.to_string())?;
        let expected_set_root =
            super::MirValueId::new(format!("local:{}", checker.caller_set_root_local.0 .0))
                .map_err(|error| error.to_string())?;
        let expected_set_root_drop = super::MirInstructionId::new(format!(
            "inst:ordinary_map_owned_any_v2_drop:{expected_set_root}:{}",
            checker.caller_set_root_drop_point.0
        ))
        .map_err(|error| error.to_string())?;
        let expected_set_root_resource = format!(
            "ordinary-map-owned-any-v2:{}",
            checker.caller_set_root_local.0 .0
        );
        let (
            expected_result_drop_point,
            expected_result_drop_place_index,
            expected_result_return_point,
        ) = match &checker.caller_result_settlement {
            crate::core::ownership::OrdinaryMapOwnedAnyV2GetOrDefaultStringResultSettlement::ExplicitDrop {
                point,
                place_index,
            } => (Some(point.clone()), Some(*place_index), None),
            crate::core::ownership::OrdinaryMapOwnedAnyV2GetOrDefaultStringResultSettlement::TailReturn {
                point,
            } => (None, None, Some(point.clone())),
        };
        if self.schema != ORDINARY_MAP_OWNED_ANY_V2_GET_OR_DEFAULT_STRING_SCHEMA
            || self.profile != ORDINARY_MAP_OWNED_ANY_V2_GET_OR_DEFAULT_STRING_PROFILE
            || checker.profile_version.canonical_text() != self.profile
            || self.owner != checker.caller_owner
            || self.callsite != checker.call_node
            || self.call_target != checker.call_target
            || self.instruction != expected_instruction
            || self.argument_order != checker.call_arguments.as_slice()
            || self.call_parameter_order.as_slice() != checker.call_parameters.as_slice()
            || self.caller_root_argument != checker.call_arguments[0]
            || self.caller_initial_root_local != checker.caller_initial_root_local
            || self.caller_root_local != checker.caller_root_local
            || self.caller_set_root_local != checker.caller_set_root_local
            || self.caller_result_local != checker.caller_result_local
            || self.caller_call_binding_point != checker.caller_call_binding_point
            || self.caller_set_value_local != checker.caller_set_value_local
            || self.caller_set_value_binding_point != checker.caller_set_value_binding_point
            || self.caller_set_value_drop_point != checker.caller_set_value_drop_point
            || self.caller_set_value_drop_place_index != checker.caller_set_value_drop_place_index
            || self.caller_default_local != checker.caller_default_local
            || self.caller_default_binding_point != checker.caller_default_binding_point
            || self.caller_result_drop_point != expected_result_drop_point
            || self.caller_result_drop_place_index != expected_result_drop_place_index
            || self.caller_result_return_point != expected_result_return_point
            || self.caller_initial_root_drop_point != checker.caller_initial_root_drop_point
            || self.caller_root_drop_point != checker.caller_root_drop_point
            || self.caller_set_root_drop_point != checker.caller_set_root_drop_point
            || self.caller_set_root_drop_place_index != checker.caller_set_root_drop_place_index
            || self.caller_initial_root_drop_instruction != expected_initial_drop
            || self.caller_root_drop_instruction != expected_root_drop
            || self.caller_set_root_drop_instruction != expected_set_root_drop
            || checker.caller_root.0 .0 != expected_set_root_resource
            || checker.caller_set_root_drop_place_index != 0
            || self.helper_map_parameter != checker.helper_map_parameter
            || self.helper_map_permission != checker.helper_map_permission
            || self.helper_map_permission != crate::core::Permission::View
            || self.helper_key_parameter != checker.helper_key_parameter
            || self.helper_default_parameter != checker.helper_default_parameter
            || self.helper_pair_binding_point != checker.helper_pair_binding_point
            || self.helper_found_condition != checker.helper_found_condition
            || self.helper_found_arm_block != checker.helper_found_arm_block
            || self.helper_default_arm_block != checker.helper_default_arm_block
            || self.helper_payload_projection != checker.helper_payload_projection
            || self.helper_unpack_cast != checker.helper_unpack_cast
            || self.helper_selected_binding_point != checker.helper_selected_binding_point
            || self.helper_selected_local != checker.helper_selected_local
            || self.helper_default_load != checker.helper_default_load
            || self.helper_pair_drop_point != checker.helper_pair_drop_point
            || self.helper_return_node != checker.helper_return_node
            || self.helper_default_pack != checker.helper_default_pack
            || self.helper_default_pack_from != checker.helper_default_pack_from
            || self.helper_default_pack_to != checker.helper_default_pack_to
            || self.type_argument != checker.call_type_argument
            || self.miss_payload_type_desc != checker.miss_payload_type
            || self.result != expected_result
            || self.root != expected_root
            || self.key != expected_key
            || self.default != expected_default
            || self.key_type != checker.call_argument_types[1]
            || self.default_type != checker.call_argument_types[2]
            || self.result_type != checker.call_result_type
            || self.default_type != self.type_argument
            || self.result_type != self.type_argument
            || self.root_type != super::types::ordinary_map_owned_any_v2_type_id()
            || self.root_type_desc != self.root_type
            || self.key_type_desc != self.key_type
            || self.default_type_desc != self.default_type
            || self.result_type_desc != self.result_type
            || self.pair_type_desc != super::types::ordinary_map_owned_any_v2_get_result_type_id()
            || self.payload_owner_type_desc
                != super::types::ordinary_map_owned_any_v2_payload_type_id()
            || self.selected_payload_type_desc != self.type_argument
            || self.type_argument
                != crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String)
            || self.miss_payload_type_desc
                != crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32)
            || !is_lower_hex_digest(&self.miss_payload_type_desc_digest)
        {
            return Err("GetOrDefault<String> MIR receipt disagrees with its exact Checker caller/callsite binding".into());
        }
        if self.caller_initial_root_local == self.caller_root_local
            || self.caller_initial_root_local == self.caller_set_root_local
            || self.caller_initial_root_drop_point == self.caller_root_drop_point
            || self.caller_initial_root_drop_point == self.caller_set_root_drop_point
            || self.caller_initial_root_drop_point == self.caller_call_binding_point
            || self.caller_root_drop_point == self.caller_call_binding_point
            || self.caller_set_root_drop_point == self.caller_call_binding_point
            || (self.caller_set_root_local == self.caller_root_local)
                != (self.caller_set_root_drop_point == self.caller_root_drop_point)
        {
            return Err(
                "GetOrDefault<String> caller root lineage or explicit settlements are not distinct"
                    .into(),
            );
        }
        if self.caller_set_value_drop_point.is_some()
            != self.caller_set_value_drop_instruction.is_some()
            || self.caller_result_drop_point.is_some()
                != self.caller_result_drop_instruction.is_some()
            || self.caller_result_drop_point.is_some() == self.caller_result_return_point.is_some()
        {
            return Err(
                "GetOrDefault<String> caller String owner settlement is incomplete or ambiguous"
                    .into(),
            );
        }
        Ok(())
    }

    pub fn validate_against_program(&self, program: &MirProgram) -> Result<(), String> {
        self.validate()?;
        if program
            .actor_execution_plan()
            .is_some_and(|plan| plan.tagged_functions.contains(&self.owner))
        {
            return Err(
                "GetOrDefault<String> caller is Actor-tagged and cannot use this ordinary callable route".into(),
            );
        }
        let derived = program.ordinary_map_owned_any_v2_get_or_default_string_receipts()?;
        if derived.as_slice() != [self.clone()] {
            return Err("GetOrDefault<String> MIR receipt differs from the uniquely derived whole-program witness".into());
        }
        if program.functions().contains_key(&self.call_target)
            || program
                .instances()
                .values()
                .any(|instance| instance.template == self.call_target)
            || program.functions().values().any(|function| {
                function.blocks.values().any(|block| {
                    block.instructions.iter().any(|instruction| {
                        matches!(
                            &instruction.kind,
                            super::MirInstructionKind::Call {
                                callee: crate::core::ir::ResolvedCallee::Function(target),
                                ..
                            } if target == &self.call_target
                        )
                    })
                })
            })
        {
            return Err(
                "GetOrDefault<String> generic helper leaked into executable MIR or retained a generic Call fallback".into(),
            );
        }
        let catalog = program.type_catalog();
        for (role, descriptor) in [
            ("root", &self.root_type_desc),
            ("key", &self.key_type_desc),
            ("default", &self.default_type_desc),
            ("result", &self.result_type_desc),
            ("pair", &self.pair_type_desc),
            ("payload owner", &self.payload_owner_type_desc),
            ("selected payload", &self.selected_payload_type_desc),
            ("miss payload", &self.miss_payload_type_desc),
        ] {
            if catalog.get(descriptor).is_none() {
                return Err(format!(
                    "GetOrDefault<String> MIR receipt references missing {role} TypeDesc '{}'",
                    descriptor.as_str()
                ));
            }
        }
        let selected = catalog
            .get(&self.selected_payload_type_desc)
            .ok_or_else(|| {
                "GetOrDefault<String> MIR receipt selected String TypeDesc is absent".to_string()
            })?;
        if selected.kind != super::types::MirTypeKind::Primitive(crate::core::PrimitiveType::String)
            || selected.layout != super::types::MirLayout::Handle
            || selected.ownership != super::types::MirOwnership::Move
            || catalog
                .validate_owned_string(&self.selected_payload_type_desc)
                .is_err()
        {
            return Err("GetOrDefault<String> selected payload is not the canonical owned String TypeDesc/glue".into());
        }
        let miss = catalog.get(&self.miss_payload_type_desc).ok_or_else(|| {
            "GetOrDefault<String> MIR receipt canonical i32 miss TypeDesc is absent".to_string()
        })?;
        if miss.kind != super::types::MirTypeKind::Primitive(crate::core::PrimitiveType::I32)
            || miss.layout != super::types::MirLayout::Scalar
            || miss.ownership != super::types::MirOwnership::Copy
            || catalog
                .validate_copy_scalar(&self.miss_payload_type_desc)
                .is_err()
            || digest(miss.canonical_text()) != self.miss_payload_type_desc_digest
        {
            return Err(
                "GetOrDefault<String> miss sentinel is not the canonical Copy i32 TypeDesc/digest"
                    .into(),
            );
        }
        Ok(())
    }

    /// Rebind this witness to the live CheckedProgram that authorized the MIR
    /// graph. This keeps native/CLI route selection from trusting a detached
    /// MIR-owned copy of the Checker receipt.
    pub(crate) fn validate_against_checked_program(
        &self,
        checked: &crate::core::CheckedProgram,
    ) -> Result<(), String> {
        self.validate()?;
        let receipts = checked
            .resource_analyses()
            .values()
            .filter_map(|analysis| {
                analysis
                    .ordinary_map_owned_any_v2_cfg_receipt
                    .as_ref()?
                    .get_or_default_string_receipt
                    .as_ref()
            })
            .collect::<Vec<_>>();
        let [checker] = receipts.as_slice() else {
            return Err(format!(
                "GetOrDefault<String> route requires exactly one CheckedProgram receipt, observed {}",
                receipts.len()
            ));
        };
        if *checker != &self.checker {
            return Err(
                "GetOrDefault<String> MIR receipt differs from the live CheckedProgram witness"
                    .into(),
            );
        }
        Ok(())
    }
}

/// Derived proof that one Checker-receipted GetAny tuple's `.0` field is
/// projected exactly once and moved into its direct Bool binding. The pair
/// itself remains the owner; this receipt carries the source-use commitment
/// and outcome identity for route validators without deciding the Bool
/// formula.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct OrdinaryMapOwnedAnyV2FoundObservationMirReceipt {
    pub schema: &'static str,
    pub profile: &'static str,
    pub owner: NodeId,
    pub operation: NodeId,
    pub get_any_instruction: super::MirInstructionId,
    pub get_any_result: OrdinaryMapOwnedAnyV2GetAnyResultReceipt,
    pub pair_binding_point: NodeId,
    pub pair_binding_local: crate::core::ir::ResolvedLocalId,
    pub pair: super::MirValueId,
    pub projection: NodeId,
    pub projection_instruction: super::MirInstructionId,
    pub projection_result: super::MirValueId,
    pub found_binding_point: NodeId,
    pub found_binding_local: crate::core::ir::ResolvedLocalId,
    pub found_binding_value: super::MirValueId,
    pub found_source_uses: std::collections::BTreeSet<NodeId>,
    pub outcome_node: NodeId,
}

impl OrdinaryMapOwnedAnyV2FoundObservationMirReceipt {
    pub fn validate(&self) -> Result<(), String> {
        if self.schema != ORDINARY_MAP_OWNED_ANY_V2_FOUND_OBSERVATION_SCHEMA
            || self.profile != ORDINARY_MAP_OWNED_ANY_V2_PROFILE
        {
            return Err("unexpected AnyOwner-v2 found-observation schema/profile".into());
        }
        if self.owner.0.trim().is_empty()
            || self.operation.0.trim().is_empty()
            || self.get_any_instruction.as_str().trim().is_empty()
            || self.pair_binding_point.0.trim().is_empty()
            || self.pair_binding_local.0 .0.trim().is_empty()
            || self.pair.as_str().trim().is_empty()
            || self.projection.0.trim().is_empty()
            || self.projection_instruction.as_str().trim().is_empty()
            || self.projection_result.as_str().trim().is_empty()
            || self.found_binding_point.0.trim().is_empty()
            || self.found_binding_local.0 .0.trim().is_empty()
            || self.found_binding_value.as_str().trim().is_empty()
            || self.found_source_uses.is_empty()
            || self.outcome_node.0.trim().is_empty()
        {
            return Err(
                "AnyOwner-v2 found-observation receipt contains an empty identity or use set"
                    .into(),
            );
        }
        if self.get_any_result.owner != self.owner
            || self.get_any_result.operation != self.operation
            || self.get_any_result.instruction != self.get_any_instruction
            || self.get_any_result.binding_point != self.pair_binding_point
            || self.get_any_result.binding_local != self.pair_binding_local
            || self.get_any_result.binding != self.pair
            || self.pair
                != super::MirValueId::new(format!("local:{}", self.pair_binding_local.0 .0))
                    .map_err(|error| error.to_string())?
            || self.projection_result
                != super::MirValueId::new(format!("expr:{}", self.projection.0))
                    .map_err(|error| error.to_string())?
            || self.projection_instruction.as_str()
                != format!("inst:managed_any_tuple_load:{}", self.projection.0)
            || self.found_binding_value
                != super::MirValueId::new(format!("local:{}", self.found_binding_local.0 .0))
                    .map_err(|error| error.to_string())?
        {
            return Err("AnyOwner-v2 found-observation receipt disagrees with its exact GetAny or binding identity".into());
        }
        self.get_any_result.validate()?;
        Ok(())
    }

    pub fn validate_against_program(&self, program: &MirProgram) -> Result<(), String> {
        self.validate()?;
        let actual = program
            .ordinary_map_owned_any_v2_found_observation_receipts()?
            .into_iter()
            .find(|receipt| {
                receipt.owner == self.owner
                    && receipt.operation == self.operation
                    && receipt.projection == self.projection
            })
            .ok_or_else(|| {
                "MIR program has no matching AnyOwner-v2 found-observation receipt".to_string()
            })?;
        if actual != *self {
            return Err(
                "AnyOwner-v2 found-observation receipt does not match Checker or MIR evidence"
                    .into(),
            );
        }
        Ok(())
    }
}

