/// Derived Core witness joining an exact Checker-owned immutable index
/// binding to its MIR `Const(0) -> Move(local)` producer and one Values unpack.
/// This is a separate route receipt because `index_local` by itself does not
/// prove the source initializer or immutability.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OrdinaryMapOwnedAnyV2ValuesLocalIndexI32MirReceipt {
    pub schema: &'static str,
    pub profile: &'static str,
    pub owner: NodeId,
    pub source_binding: crate::core::ir::ResolvedLocalId,
    pub source_binding_point: NodeId,
    pub source_initializer: NodeId,
    pub literal_value: i64,
    pub index_type: crate::core::ir::ResolvedTypeId,
    pub index_expression: NodeId,
    pub const_instruction: super::MirInstructionId,
    pub const_result: super::MirValueId,
    pub binding_instruction: super::MirInstructionId,
    pub index_local: super::MirValueId,
    pub unpack: OrdinaryMapOwnedAnyV2ValuesUnpackResultReceipt,
    pub(crate) checker_source:
        crate::core::ownership::OrdinaryMapOwnedAnyV2ValuesLocalIndexI32Receipt,
}

impl OrdinaryMapOwnedAnyV2ValuesLocalIndexI32MirReceipt {
    pub fn validate(&self) -> Result<(), String> {
        if self.schema != ORDINARY_MAP_OWNED_ANY_V2_VALUES_LOCAL_INDEX_I32_SCHEMA
            || self.profile
                != super::route::ORDINARY_MAP_OWNED_ANY_V2_VALUES_LOCAL_INDEX_I32_PROFILE
            || self.literal_value != 0
            || self.index_type
                != crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32)
            || self.checker_source.binding_mutable
            || self.checker_source.binding != self.source_binding
            || self.checker_source.binding_point != self.source_binding_point
            || self.checker_source.initializer != self.source_initializer
            || self.checker_source.literal_value != self.literal_value
            || self.checker_source.index_type != self.index_type
            || self.checker_source.index_expression != self.index_expression
            || self.checker_source.unpack_cast != self.unpack.cast
            || self.checker_source.unpack_binding != self.unpack.result_binding_local
            || self.checker_source.unpack_binding_point != self.unpack.result_binding_point
            || self.checker_source.snapshot_binding != self.unpack.values_binding_local
            || self.unpack.index_expression != self.index_expression
            || self.unpack.index != self.index_local
            || self.index_local
                != super::MirValueId::new(format!("local:{}", self.source_binding.0 .0))
                    .map_err(|error| error.to_string())?
            || self.const_result
                != super::MirValueId::new(format!("expr:{}", self.source_initializer.0))
                    .map_err(|error| error.to_string())?
            || self.const_instruction
                != super::MirInstructionId::new(format!("inst:const:{}", self.source_initializer.0))
                    .map_err(|error| error.to_string())?
            || self.binding_instruction
                != super::MirInstructionId::new(format!(
                    "inst:bind:{}",
                    self.source_binding_point.0
                ))
                .map_err(|error| error.to_string())?
            || self.checker_source.source_uses
                != std::collections::BTreeSet::from([self.index_expression.clone()])
        {
            return Err("Values local-index MIR receipt disagrees with the exact Checker source binding or Values unpack".into());
        }
        self.unpack.validate()?;
        Ok(())
    }

    pub fn validate_against_program(&self, program: &MirProgram) -> Result<(), String> {
        self.validate()?;
        let derived = program.ordinary_map_owned_any_v2_values_local_index_i32_receipts()?;
        if derived.as_slice() != [self.clone()] {
            return Err("Values local-index MIR receipt differs from the uniquely derived whole-program witness".into());
        }
        Ok(())
    }
}

