    /// Return only the existing local ExplicitDrop Values witnesses after
    /// proving that every omitted returned producer is covered by one exact
    /// V1 or cross-call String producer-caller receipt. No other result
    /// settlement is filtered.
    pub fn ordinary_map_owned_any_v2_values_result_receipts_excluding_producer_caller(
        &self,
        bridges: &[OrdinaryMapOwnedAnyV2ValuesProducerCallerMirReceipt],
    ) -> Result<Vec<OrdinaryMapOwnedAnyV2ValuesResultReceipt>, String> {
        let derived_bridges = self.ordinary_map_owned_any_v2_values_producer_caller_receipts()?;
        if derived_bridges != bridges {
            return Err("filtered Values result census requires the exact derived producer-caller receipt set".into());
        }
        let mut approved_returns = bridges
            .iter()
            .map(|receipt| {
                receipt.validate_against_program(self)?;
                Ok((
                    receipt.producer_owner.clone(),
                    receipt.checker_producer.values_operation.clone(),
                ))
            })
            .collect::<Result<BTreeSet<_>, String>>()?;
        let crosscall_string_receipts =
            self.ordinary_map_owned_any_v2_values_crosscall_string_caller_receipts()?;
        for receipt in &crosscall_string_receipts {
            receipt.validate_against_program(self)?;
            let identity = (
                receipt.producer_owner.clone(),
                receipt.checker_producer.values_operation.clone(),
            );
            if !approved_returns.insert(identity) {
                return Err(
                    "one Values producer Return cannot be covered by both producer-caller profiles"
                        .into(),
                );
            }
        }
        let mut observed_returns = BTreeSet::new();
        let mut values_operation_count = 0usize;
        for function in self.functions().values() {
            values_operation_count += function
                .blocks
                .values()
                .flat_map(|block| &block.instructions)
                .filter(|instruction| {
                    matches!(
                        instruction.kind,
                        super::MirInstructionKind::OrdinaryMapOwnedAnyV2Values { .. }
                    )
                })
                .count();
            let Some(cfg) = function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_ref()
            else {
                continue;
            };
            for result in cfg.result_receipts.iter().filter(|result| {
                result.kind == crate::core::OrdinaryMapOwnedAnyV2ActionKind::Values
                    && result.settlement
                        == crate::core::OrdinaryMapOwnedAnyV2ResultSettlementKind::Return
            }) {
                let identity = (function.owner.clone(), result.operation.clone());
                let producer_matches = cfg
                    .values_producer_return_receipt
                    .as_ref()
                    .is_some_and(|producer| producer.matches_returned_result(result));
                if !producer_matches
                    || !approved_returns.contains(&identity)
                    || !observed_returns.insert(identity)
                {
                    return Err("filtered Values result census encountered an unapproved or duplicated producer Return".into());
                }
            }
        }
        if observed_returns != approved_returns
            || values_operation_count
                != observed_returns.len()
                    + self
                        .ordinary_map_owned_any_v2_values_result_receipts()?
                        .len()
        {
            return Err(
                "filtered Values result census has an omitted or extra Values operation".into(),
            );
        }
        self.ordinary_map_owned_any_v2_values_result_receipts()
    }

