    fn ordinary_map_v2_program() -> MirProgram {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/mir_ordinary_map_any_owner_v2_record.mimi");
        let source =
            include_str!("../../../tests/fixtures/mir_ordinary_map_any_owner_v2_record.mimi");
        let tokens = crate::lexer::Lexer::new(source)
            .tokenize()
            .expect("V2 fixture lexes");
        let file = crate::parser::Parser::new(tokens)
            .parse_file()
            .expect("V2 fixture parses");
        let mut loader = crate::loader::ModuleLoader::new(
            path.parent()
                .expect("V2 fixture has a parent directory")
                .to_path_buf(),
        );
        loader
            .load_main_with_file(&path, file)
            .expect("V2 fixture imports load");
        let mut file = loader.merge_all().expect("V2 fixture imports merge");
        crate::loader::merge_prelude_into(&mut file);
        let checked = crate::core::check_program(&file).expect("V2 fixture checks");
        let admission = crate::core::mir::classify_canonical_mir_route_admission(&checked);
        assert_eq!(
            admission.ordinary_map_owned_any_v2,
            crate::core::mir::OrdinaryMapOwnedAnyV2Admission::CompleteCoverage,
            "fixture has the complete owner-v2 Checker profile"
        );
        // Match the canonical route's prelude exclusion for a complete V2
        // profile, while keeping these receipt tests independent of route
        // composition and production-readiness gates.
        let excluded = checked
            .source_registry()
            .records()
            .iter()
            .filter(|record| record.key.as_str() == "stdlib:prelude.mimi")
            .map(|record| record.id)
            .collect::<std::collections::HashSet<_>>();
        let program = MirProgram::from_checked_program_excluding_sources(&checked, &excluded)
            .expect("complete V2 Checker profile lowers with canonical route exclusions");
        let materialized_receipt = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("Checker-derived V2 payload selection validates")
            .expect("fixture Set actions produce a payload selection");
        assert_eq!(
            materialized_receipt.profile,
            ORDINARY_MAP_OWNED_ANY_V2_PROFILE
        );
        assert!(materialized_receipt
            .validate_against_program(&program)
            .is_ok());
        program
    }

