    #[test]
    fn get_or_default_string_mir_census_requires_the_set_source_drop_action() {
        use crate::core::mir::{MirInstructionKind as Instruction, MirValueId};
        use crate::core::OrdinaryMapOwnedAnyV2ActionKind as Action;

        let (_checked, mut program) = get_or_default_string_alias_program();
        let receipts = program
            .ordinary_map_owned_any_v2_get_or_default_string_receipts()
            .expect("exact alias Set-source and receiver Drops derive");
        let [receipt] = receipts.as_slice() else {
            panic!("alias fixture has exactly one String receipt");
        };
        assert_ne!(
            receipt.caller_set_root_local, receipt.caller_root_local,
            "fixture distinguishes persistent Set source from immutable alias receiver"
        );
        assert_ne!(
            receipt.caller_set_root_drop_point, receipt.caller_root_drop_point,
            "fixture has separate source-root and alias-root Checker Drop points"
        );
        let payload_local = receipt
            .caller_set_value_local
            .as_ref()
            .expect("alias fixture binds its String Set payload");
        let payload_drop_instruction = receipt
            .caller_set_value_drop_instruction
            .as_ref()
            .expect("bound Set payload has an exact MIR Drop");
        let payload_value = MirValueId::new(format!("local:{}", payload_local.0 .0))
            .expect("payload local has canonical MIR identity");
        let payload_drop_count = program
            .functions()
            .get(&receipt.owner)
            .expect("alias caller MIR function exists")
            .blocks
            .values()
            .flat_map(|block| block.instructions.iter())
            .filter(|instruction| {
                &instruction.id == payload_drop_instruction
                    && matches!(
                        &instruction.kind,
                        crate::core::mir::MirInstructionKind::Drop { value }
                            if value == &payload_value
                    )
            })
            .count();
        assert_eq!(
            payload_drop_count, 1,
            "the bound payload has one exact local Drop"
        );
        let owner = receipt.owner.clone();
        let source_value = MirValueId::new(format!("local:{}", receipt.caller_set_root_local.0 .0))
            .expect("Set-source local has canonical MIR identity");
        let source_point = receipt.caller_set_root_drop_point.clone();
        let source_drop_instruction = receipt.caller_set_root_drop_instruction.clone();

        let function = program
            .function_mut_for_test(&owner)
            .expect("alias caller MIR function exists");
        let mut removed_instruction = false;
        for block in function.blocks.values_mut() {
            if let Some(index) = block.instructions.iter().position(|instruction| {
                instruction.id == source_drop_instruction
                    && matches!(
                        &instruction.kind,
                        Instruction::OrdinaryMapOwnedAnyV2Drop { root }
                            if root == &source_value
                    )
            }) {
                block.instructions.remove(index);
                removed_instruction = true;
                break;
            }
        }
        assert!(removed_instruction, "remove the exact Set-source MIR Drop");

        let action_count_before = function.ownership.checker_ordinary_map_owned_any_v2.len();
        function
            .ownership
            .checker_ordinary_map_owned_any_v2
            .retain(|action| {
                !(action.kind == Action::Drop
                    && action.point == source_point
                    && action.local == source_value
                    && action.instruction == source_drop_instruction)
            });
        assert_eq!(
            function.ownership.checker_ordinary_map_owned_any_v2.len(),
            action_count_before - 1,
            "remove only the matching projected source-root Drop action while preserving CFG"
        );

        let error = program
            .ordinary_map_owned_any_v2_get_or_default_string_receipts()
            .expect_err("standalone MIR census cannot hide the missing source-root settlement");
        assert!(
            error.contains("Set-result Map root has no unique exact MIR Drop")
                || error.contains("caller root Drop evidence is incomplete"),
            "failure identifies the missing exact source-root evidence: {error}"
        );
    }

    #[test]
    fn get_or_default_string_mir_census_rejects_a_duplicate_checker_receipt() {
        let fixture = "tests/fixtures/mir_ordinary_map_owned_any_v2_get_or_default_string_duplicate_receipt.mimi";
        let (_checked, mut program) = get_or_default_string_program_for_fixture(
            fixture,
            include_str!(
                "../../../tests/fixtures/mir_ordinary_map_owned_any_v2_get_or_default_string_duplicate_receipt.mimi"
            ),
        );
        let receipts = program
            .ordinary_map_owned_any_v2_get_or_default_string_receipts()
            .expect("exact alias receipt derives");
        let [receipt] = receipts.as_slice() else {
            panic!("alias fixture has exactly one String receipt");
        };
        let duplicate_owner = program
            .functions()
            .keys()
            .find(|owner| **owner != receipt.owner)
            .cloned()
            .expect("fixture has a second source-owned function in the scoped MIR graph");
        let duplicated_cfg = program
            .functions()
            .get(&receipt.owner)
            .and_then(|function| {
                function
                    .ownership
                    .checker_ordinary_map_owned_any_v2_cfg_receipt
                    .clone()
            })
            .expect("canonical String caller has its Checker V2 CFG census");
        let duplicate_function = program
            .function_mut_for_test(&duplicate_owner)
            .expect("second source-owned MIR function exists");
        duplicate_function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt = Some(duplicated_cfg);
        let duplicate_cfg = duplicate_function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("install a forged second Checker V2 CFG census");
        assert_eq!(
            duplicate_cfg.get_or_default_string_receipt.as_ref(),
            Some(&receipt.checker),
            "the second owner carries the exact duplicate Checker cross-call receipt"
        );

        let error = program
            .ordinary_map_owned_any_v2_get_or_default_string_receipts()
            .expect_err("the cross-call census rejects a duplicate Checker receipt");
        assert!(
            error.contains("unique Checker cross-call receipt"),
            "failure identifies the duplicate Checker receipt: {error}"
        );
    }

    #[test]
    fn get_or_default_i32_mir_receipt_rejects_forged_crosscall_bindings() {
        use crate::core::mir::{MirInstructionKind as I, MirValueId};

        let (checked, program) = get_or_default_i32_program();
        let receipts = program
            .ordinary_map_owned_any_v2_get_or_default_i32_receipts()
            .expect("GetOrDefault<i32> receipt derives");
        let [receipt] = receipts.as_slice() else {
            panic!("one exact GetOrDefault<i32> callsite");
        };
        receipt
            .validate_against_checked_program(&checked)
            .expect("receipt is rebound to the live Checker witness");
        receipt
            .validate_against_program(&program)
            .expect("receipt is independently derived from canonical MIR");

        let mut forged = receipt.clone();
        forged.owner = NodeId("function:forged_caller".into());
        assert!(forged.validate().is_err(), "caller owner is bound");

        let mut forged = receipt.clone();
        forged.root = MirValueId::new("local:forged_root").expect("test root identity");
        assert!(forged.validate().is_err(), "caller root operand is bound");

        let mut forged = receipt.clone();
        forged.key = MirValueId::new("expr:forged_key").expect("test key identity");
        assert!(forged.validate().is_err(), "static key operand is bound");

        let mut forged = receipt.clone();
        forged.default = MirValueId::new("expr:forged_default").expect("test default identity");
        assert!(forged.validate().is_err(), "default operand is bound");

        let mut forged = receipt.clone();
        forged.call_target = NodeId("function:user_get_or_default".into());
        assert!(
            forged.validate().is_err(),
            "canonical helper target is bound"
        );

        let mut forged = receipt.clone();
        forged.type_argument = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I64);
        assert!(forged.validate().is_err(), "i32 type argument is bound");

        let mut forged = receipt.clone();
        forged.argument_order.swap(0, 1);
        assert!(
            forged.validate().is_err(),
            "ordered helper arguments are bound"
        );

        let mut forged = receipt.clone();
        forged.call_parameter_order.swap(0, 1);
        assert!(
            forged.validate().is_err(),
            "caller arguments remain bound to their exact helper formal parameters"
        );

        let mut forged = receipt.clone();
        forged.root_type_desc = forged.key_type.clone();
        assert!(forged.validate().is_err(), "caller root TypeDesc is bound");

        let mut forged = receipt.clone();
        forged.key_type_desc = forged.default_type.clone();
        assert!(forged.validate().is_err(), "String key TypeDesc is bound");

        let mut forged = receipt.clone();
        forged.default_type_desc = forged.key_type.clone();
        assert!(forged.validate().is_err(), "i32 default TypeDesc is bound");

        let mut forged = receipt.clone();
        forged.result_type_desc = forged.key_type.clone();
        assert!(forged.validate().is_err(), "i32 result TypeDesc is bound");

        let mut forged = receipt.clone();
        forged.pair_type_desc = forged.root_type.clone();
        assert!(forged.validate().is_err(), "GetAny pair TypeDesc is bound");

        let mut forged = receipt.clone();
        forged.payload_owner_type_desc = forged.root_type.clone();
        assert!(
            forged.validate().is_err(),
            "V2 payload-owner TypeDesc is bound"
        );

        let mut forged = receipt.clone();
        forged.checker.caller_set_value_type =
            crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I64);
        assert!(
            forged.validate_against_program(&program).is_err(),
            "caller Set payload descriptor remains bound to the Checker/MIR lineage"
        );

        let mut forged = receipt.clone();
        forged.checker.caller_query_key_bytes = "forged-key".into();
        assert!(
            forged.validate_against_program(&program).is_err(),
            "caller query-key literal remains bound to Checker and MIR"
        );

        let mut forged = receipt.clone();
        forged.checker.caller_default_i32 = 73;
        assert!(
            forged.validate_against_program(&program).is_err(),
            "caller default literal remains bound to Checker and MIR"
        );

        let mut forged = receipt.clone();
        forged.selected_payload_type_desc = forged.key_type.clone();
        assert!(forged.validate().is_err(), "selected i32 TypeDesc is bound");

        let mut forged = receipt.clone();
        forged.helper_found_arm_block = NodeId("block:forged_found_arm".into());
        assert!(forged.validate().is_err(), "found-arm binding is bound");

        let mut forged = receipt.clone();
        forged.helper_default_arm_block = NodeId("block:forged_default_arm".into());
        assert!(forged.validate().is_err(), "default-arm binding is bound");

        let mut forged = receipt.clone();
        forged.helper_unpack_cast = NodeId("expr:unpack_outside_found_arm".into());
        assert!(
            forged.validate().is_err(),
            "selected-value unpack binding is bound"
        );

        let mut forged = receipt.clone();
        forged.helper_default_load = NodeId("expr:forged_default_load".into());
        assert!(forged.validate().is_err(), "miss default source is bound");

        let mut forged = receipt.clone();
        forged.caller_root_drop_instruction = crate::core::mir::MirInstructionId::new(
            "inst:ordinary_map_owned_any_v2_drop:local:forged_root:point:forged",
        )
        .expect("test Drop instruction identity");
        assert!(
            forged.validate().is_err(),
            "caller ownership Drop edge is bound"
        );

        let mut changed_program = program.clone();
        let mut caller = changed_program
            .functions()
            .get(&receipt.owner)
            .expect("caller MIR function")
            .clone();
        let mut changed_call_target = false;
        for block in caller.blocks.values_mut() {
            for instruction in &mut block.instructions {
                if instruction.id == receipt.instruction {
                    if let I::OrdinaryMapOwnedAnyV2GetOrDefaultI32 { call_target, .. } =
                        &mut instruction.kind
                    {
                        *call_target = NodeId("function:forged_callee".into());
                        changed_call_target = true;
                    }
                }
            }
        }
        assert!(
            changed_call_target,
            "fixture has its receipted call instruction"
        );
        changed_program.replace_function_for_test_only(caller);
        assert!(
            changed_program
                .ordinary_map_owned_any_v2_get_or_default_i32_receipts()
                .is_err(),
            "MIR re-derivation rejects a forged helper target"
        );
    }

    #[test]
    fn get_or_default_i32_mir_receipt_rechecks_main_direct_call_reachability() {
        use crate::core::ir::ResolvedCallee;
        use crate::core::mir::MirInstructionKind as I;

        let (_checked, program) = get_or_default_i32_reachable_helper_program();
        let receipts = program
            .ordinary_map_owned_any_v2_get_or_default_i32_receipts()
            .expect("the main-reachable ordinary helper receipt derives");
        let [receipt] = receipts.as_slice() else {
            panic!("one helper-owned GetOrDefault<i32> receipt");
        };
        assert_eq!(receipt.owner, NodeId("function:lookup".into()));
        receipt
            .validate_against_program(&program)
            .expect("the direct main-to-helper call proves MIR reachability");

        let main = NodeId("function:main".into());
        let mut main_function = program
            .functions()
            .get(&main)
            .expect("MIR main function")
            .clone();
        let mut redirected = false;
        for instruction in main_function
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
        {
            if let I::Call {
                callee: ResolvedCallee::Function(target),
                ..
            } = &mut instruction.kind
            {
                if target == &receipt.owner {
                    *target = main.clone();
                    redirected = true;
                }
            }
        }
        assert!(
            redirected,
            "fixture has a direct MIR Call from main to lookup"
        );

        let mut tampered = program.clone();
        tampered.replace_function_for_test_only(main_function);
        let error = tampered
            .ordinary_map_owned_any_v2_get_or_default_i32_receipts()
            .expect_err("MIR receipt derivation independently rejects an unreachable caller");
        assert!(
            error.contains("not reachable from function:main"),
            "the rejection identifies the broken direct-call proof: {error}"
        );
        assert!(
            receipt.validate_against_program(&tampered).is_err(),
            "a previously valid receipt cannot survive caller removal from the MIR graph"
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_println_binds_source_pair_selection_and_drop() {
        let source = r#"
func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "k", "text\0中")
    let pair = map_get(root, "k")
    drop(empty)
    drop(root)
    println(pair.1)
    drop(pair)
    0
}
"#;
        let program = ordinary_map_v2_unpack_program(source);
        const {
            assert!(!super::super::ORDINARY_MAP_OWNED_ANY_V2_PRODUCTION_READY);
        };
        let receipts = program
            .ordinary_map_owned_any_v2_println_receipts()
            .expect("exact V2 stdout receipt");
        let [receipt] = receipts.as_slice() else {
            panic!("one direct stdout borrow")
        };
        receipt
            .validate_against_program(&program)
            .expect("source/MIR/TypeDesc evidence agrees");
        assert_eq!(
            receipt.selected_types.len(),
            2,
            "selected String plus canonical i32 miss"
        );
        let owner = &receipt.owner;
        let function = program.functions().get(owner).expect("source owner");
        assert!(
            function
                .blocks
                .values()
                .flat_map(|block| &block.instructions)
                .all(|instruction| !matches!(&instruction.kind,
            super::super::MirInstructionKind::Project { base, .. } if base == &receipt.pair)),
            "borrow must not materialize a v1 or retained payload projection"
        );

        let mut wrong_digest = receipt.clone();
        wrong_digest.payload_selection_digest = "0".repeat(64);
        assert!(wrong_digest.validate_against_program(&program).is_err());
        let mut wrong_projection = receipt.clone();
        wrong_projection.projection = receipt.call.clone();
        assert!(wrong_projection.validate_against_program(&program).is_err());

        for case in 0..5 {
            let mut forged = program.clone();
            let mut function = function.clone();
            let source_result = function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("source CFG receipt")
                .result_receipts
                .first_mut()
                .expect("GetAny result receipt");
            match case {
                0 => source_result.payload_println = None,
                1 => {
                    source_result
                        .payload_println
                        .as_mut()
                        .expect("observation")
                        .call = receipt.get_any.operation.clone()
                }
                2 => {
                    source_result
                        .payload_println
                        .as_mut()
                        .expect("observation")
                        .projection = receipt.call.clone()
                }
                3 => source_result.binding = receipt.get_any.source_local.clone(),
                _ => source_result.settlement_point = Some(receipt.call.clone()),
            }
            forged.replace_function_for_test_only(function);
            assert!(
                forged.ordinary_map_owned_any_v2_println_receipts().is_err(),
                "forged source receipt case {case} must fail closed"
            );
        }
        let mut forged = program.clone();
        let mut function = function.clone();
        let block = function
            .blocks
            .get_mut(&function.entry.clone())
            .expect("entry");
        let print_index = block
            .instructions
            .iter()
            .position(|instruction| instruction.id == receipt.instruction)
            .expect("stdout op");
        let drop_index = block
            .instructions
            .iter()
            .position(|instruction| instruction.id == receipt.get_any.settlement_instruction)
            .expect("pair Drop");
        block.instructions.swap(print_index, drop_index);
        forged.replace_function_for_test_only(function);
        assert!(
            forged.ordinary_map_owned_any_v2_println_receipts().is_err(),
            "drop-before-observe must fail before output"
        );
    }

