    #[test]
    fn removed_key_checked_miss_rejects_formula_node_identity_drift() {
        for field in [
            "outcome_node",
            "found_false_node",
            "payload_zero_node",
            "zero_literal_node",
        ] {
            let mut program = ordinary_map_v2_unpack_program(include_str!(
                "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_removed_key_checked_miss.mimi"
            ));
            let owner = NodeId("function:main".into());
            let mut function = program.functions().get(&owner).expect("main MIR").clone();
            let formula = &mut function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .and_then(|cfg| cfg.removed_key_checked_miss_receipt.as_mut())
                .expect("private RemovedKeyCheckedMiss receipt")
                .observation_formula;
            let forged = NodeId(format!("forged:{field}"));
            match field {
                "outcome_node" => formula.outcome_node = forged,
                "found_false_node" => formula.found_false_node = forged,
                "payload_zero_node" => formula.payload_zero_node = forged,
                "zero_literal_node" => formula.zero_literal_node = forged,
                _ => unreachable!(),
            }
            program.replace_function_for_test_only(function);

            let error = program
                .ordinary_map_owned_any_v2_removed_key_checked_miss_receipt()
                .expect_err("formula node identities must join the exact scalar-tail proof");
            assert!(
                error.contains("RemovedKeyCheckedMiss"),
                "{field} drift produced an unrelated diagnostic: {error}"
            );
        }
    }

