    #[test]
    fn removed_key_checked_miss_rejects_private_root_drop_mutations() {
        use crate::core::mir::MirInstructionKind as Instruction;

        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_removed_key_checked_miss.mimi"
        );
        let original = ordinary_map_v2_unpack_program(source);
        let receipt = original
            .ordinary_map_owned_any_v2_removed_key_checked_miss_receipt()
            .expect("RemovedKeyCheckedMiss receipt derives")
            .expect("fixture selects RemovedKeyCheckedMiss");
        let owner = NodeId("function:main".into());
        let original_function = original.functions().get(&owner).expect("main MIR");
        let root_for_instruction = |id: &crate::core::mir::MirInstructionId| {
            original_function
                .blocks
                .values()
                .flat_map(|block| block.instructions.iter())
                .find(|instruction| &instruction.id == id)
                .and_then(|instruction| match &instruction.kind {
                    Instruction::OrdinaryMapOwnedAnyV2Drop { root } => Some(root.clone()),
                    _ => None,
                })
                .expect("receipt identifies a root Drop")
        };
        let root_ids = receipt
            .root_drop_instructions
            .iter()
            .map(root_for_instruction)
            .collect::<Vec<_>>();
        assert_eq!(root_ids.len(), 3);
        assert_eq!(
            root_ids
                .iter()
                .collect::<std::collections::BTreeSet<_>>()
                .len(),
            3
        );

        let reject = |mutated: MirProgram, reason: &str| {
            let result =
                validate_ordinary_map_owned_any_v2_removed_key_checked_miss_mir_route(&mutated);
            assert!(result.is_err(), "{reason} must fail closed; got {result:?}");
            let forged_route =
                mutated.route_receipt(ORDINARY_MAP_OWNED_ANY_V2_REMOVED_KEY_CHECKED_MISS_PROFILE);
            assert!(
                forged_route.validate_against_program(&mutated).is_err(),
                "{reason} must also be rejected by the public profile receipt validator"
            );
        };

        let first_drop = receipt.root_drop_instructions[0].clone();
        let mut missing = original.clone();
        let mut function = original_function.clone();
        let mut removed = false;
        for block in function.blocks.values_mut() {
            if let Some(index) = block
                .instructions
                .iter()
                .position(|instruction| instruction.id == first_drop)
            {
                block.instructions.remove(index);
                removed = true;
                break;
            }
        }
        assert!(removed, "fixture has the first receipted root Drop");
        missing.replace_function_for_test_only(function);
        reject(missing, "a missing persistent-root Drop instruction");

        let mut duplicated = original.clone();
        let mut function = original_function.clone();
        let mut copied = None;
        for block in function.blocks.values_mut() {
            if let Some(instruction) = block
                .instructions
                .iter()
                .find(|instruction| instruction.id == first_drop)
            {
                copied = Some(instruction.clone());
                break;
            }
        }
        let duplicate = copied.expect("fixture has the first receipted root Drop");
        function
            .blocks
            .get_mut(&function.entry.clone())
            .expect("main entry")
            .instructions
            .push(duplicate);
        duplicated.replace_function_for_test_only(function);
        reject(duplicated, "a duplicated persistent-root Drop instruction");

        let mut wrong_root = original.clone();
        let mut function = original_function.clone();
        let mut changed = false;
        for block in function.blocks.values_mut() {
            if let Some(instruction) = block
                .instructions
                .iter_mut()
                .find(|instruction| instruction.id == first_drop)
            {
                instruction.kind = Instruction::OrdinaryMapOwnedAnyV2Drop {
                    root: root_ids[1].clone(),
                };
                changed = true;
                break;
            }
        }
        assert!(changed, "fixture has the first receipted root Drop");
        wrong_root.replace_function_for_test_only(function);
        reject(wrong_root, "a root Drop redirected to another lineage root");
    }

    #[test]
    fn removed_key_checked_miss_rejects_missing_or_forged_private_checker_receipts() {
        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_removed_key_checked_miss.mimi"
        );
        let original = ordinary_map_v2_unpack_program(source);
        let owner = NodeId("function:main".into());

        let mut missing = original.clone();
        let mut function = original.functions().get(&owner).expect("main MIR").clone();
        function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private Checker V2 CFG receipt")
            .removed_key_checked_miss_receipt = None;
        missing.replace_function_for_test_only(function);
        assert!(
            validate_ordinary_map_owned_any_v2_removed_key_checked_miss_mir_route(&missing)
                .is_err(),
            "the MIR graph cannot stand in for missing embedded Checker authority"
        );

        let mut forged_key = original.clone();
        let mut function = original.functions().get(&owner).expect("main MIR").clone();
        let private_receipt = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .and_then(|cfg| cfg.removed_key_checked_miss_receipt.as_mut())
            .expect("private RemovedKeyCheckedMiss receipt");
        private_receipt.key_bytes = b"another-key".to_vec();
        forged_key.replace_function_for_test_only(function);
        assert!(
            validate_ordinary_map_owned_any_v2_removed_key_checked_miss_mir_route(&forged_key)
                .is_err(),
            "a private Checker receipt with a forged static key must fail closed"
        );

        let mut forged_owner_local = original.clone();
        let mut function = original.functions().get(&owner).expect("main MIR").clone();
        let private_receipt = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .and_then(|cfg| cfg.removed_key_checked_miss_receipt.as_mut())
            .expect("private RemovedKeyCheckedMiss receipt");
        private_receipt.new_action.local =
            crate::core::ir::ResolvedLocalId(NodeId("forged:new-owner-local".into()));
        forged_owner_local.replace_function_for_test_only(function);
        assert!(
            validate_ordinary_map_owned_any_v2_removed_key_checked_miss_mir_route(
                &forged_owner_local,
            )
            .is_err(),
            "the private New owner/root identity must bind the exact persistent lineage"
        );

        let mut forged_key_digest = original.clone();
        let mut function = original.functions().get(&owner).expect("main MIR").clone();
        let private_receipt = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .and_then(|cfg| cfg.removed_key_checked_miss_receipt.as_mut())
            .expect("private RemovedKeyCheckedMiss receipt");
        private_receipt.get_action.key_static_digest = Some("0".repeat(64));
        forged_key_digest.replace_function_for_test_only(function);
        assert!(
            validate_ordinary_map_owned_any_v2_removed_key_checked_miss_mir_route(
                &forged_key_digest,
            )
            .is_err(),
            "the private GetAny key digest must bind the same literal key as Set and Remove"
        );

        let mut forged_formula_binding = original.clone();
        let mut function = original.functions().get(&owner).expect("main MIR").clone();
        let private_receipt = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .and_then(|cfg| cfg.removed_key_checked_miss_receipt.as_mut())
            .expect("private RemovedKeyCheckedMiss receipt");
        private_receipt.observation_formula.found_binding =
            crate::core::ir::ResolvedLocalId(NodeId("forged:found-binding".into()));
        forged_formula_binding.replace_function_for_test_only(function);
        assert!(
            validate_ordinary_map_owned_any_v2_removed_key_checked_miss_mir_route(
                &forged_formula_binding,
            )
            .is_err(),
            "the private found=false conjunct must bind the exact found projection"
        );
    }

