    #[test]
    fn ordinary_map_v2_values_oob_receipt_has_no_payload_selection_and_rejects_forgery() {
        // Keep this in the canonical three-entry i32/Label/String profile;
        // bool-only and incomplete snapshot shapes are outside this closed V2 catalog.
        let program = ordinary_map_v2_unpack_program(
            r#"
            type Label { text: string }
            func main() -> i32 {
                let label = Label { text: "payload Label" }
                let text = "payload String"
                let empty = map_new()
                let numbers = map_set(empty, "number", 42)
                let labels = map_set(numbers, "label", label)
                let mixed = map_set(labels, "string", text)
                let snapshot = values(mixed)
                let rejected = snapshot[3] as i32
                let rejected_label = snapshot[3] as Label
                drop(rejected_label)
                drop(snapshot)
                drop(empty)
                drop(numbers)
                drop(labels)
                drop(mixed)
                drop(label)
                drop(text)
                0
            }
            "#,
        );
        let receipts = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("static OOB Values unpack derives a separate receipt");
        assert_eq!(
            receipts.len(),
            2,
            "both supported OOB targets are receipted"
        );
        let oob = crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::AlwaysOutOfBounds {
            raw_index: 3,
            snapshot_len: 3,
        };
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let label_type = program
            .type_catalog()
            .iter()
            .find(|(type_id, _)| {
                crate::core::mir::reference::is_canonical_v2_label_type(
                    program.type_catalog(),
                    type_id,
                )
            })
            .map(|(type_id, _)| type_id.clone())
            .expect("canonical Label TypeDesc");
        let i32_receipt = receipts
            .iter()
            .find(|receipt| receipt.conversion_to == i32_type)
            .expect("i32 OOB receipt");
        let label_receipt = receipts
            .iter()
            .find(|receipt| receipt.conversion_to == label_type)
            .expect("Label OOB receipt");
        assert_eq!(i32_receipt.index_disposition, oob);
        assert_eq!(label_receipt.index_disposition, oob);
        assert!(i32_receipt.payload_type_desc_digest.len() == 64);
        assert!(label_receipt.payload_type_desc_digest.len() == 64);
        assert!(i32_receipt.validate_against_program(&program).is_ok());
        assert!(label_receipt.validate_against_program(&program).is_ok());

        let owner = NodeId("function:main".into());
        let function = program.functions().get(&owner).expect("main MIR");
        let checker = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("private Checker Values receipt")
            .values_unpack_receipts
            .iter()
            .find(|checker| checker.conversion_to == i32_type)
            .expect("i32 Checker Values receipt");
        let label_checker = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("private Checker Values receipt")
            .values_unpack_receipts
            .iter()
            .find(|checker| checker.conversion_to == label_type)
            .expect("Label Checker Values receipt");
        assert_eq!(checker.index_disposition, oob);
        assert_eq!(label_checker.index_disposition, oob);
        assert!(checker.payload_selection.is_empty());
        assert!(label_checker.payload_selection.is_empty());
        let selection = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("payload-selection derivation")
            .expect("persistent Map action selection receipt");
        assert!(
            selection
                .selected_types
                .iter()
                .any(|selected| selected.type_id == i32_type),
            "the Map contains i32, but this exact index remains an OOB result"
        );

        let mut wrong_length = i32_receipt.clone();
        wrong_length.index_disposition =
            crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::AlwaysOutOfBounds {
                raw_index: 3,
                snapshot_len: 4,
            };
        assert!(
            wrong_length.validate().is_err(),
            "raw index 3 is in bounds for a claimed snapshot length of 4"
        );

        let mut forged_selection = i32_receipt.clone();
        forged_selection.index_disposition =
            crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::SelectedPayload;
        assert!(
            forged_selection.validate_against_program(&program).is_err(),
            "a fabricated selected-payload disposition cannot replace the rebuilt OOB outcome"
        );

        let mut forged_checker = program.clone();
        let mut function = program.functions().get(&owner).expect("main MIR").clone();
        let private_checker = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private Checker CFG receipt")
            .values_unpack_receipts
            .first_mut()
            .expect("one Checker Values receipt");
        private_checker.index_disposition =
            crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::SelectedPayload;
        private_checker.payload_selection = vec![NodeId("forged:payload-selection".into())];
        forged_checker.replace_function_for_test_only(function);
        assert!(
            forged_checker
                .ordinary_map_owned_any_v2_values_unpack_result_receipts()
                .is_err(),
            "MIR independently rejects forged Checker selection evidence for an OOB index"
        );
    }

    #[test]
    fn ordinary_map_v2_values_oob_receipt_allows_target_absent_from_selected_types() {
        let program = ordinary_map_v2_unpack_program(
            r#"
            func main() -> i32 {
                let text = "only selected String payload"
                let empty = map_new()
                let root = map_set(empty, "string", text)
                let snapshot = values(root)
                let rejected = snapshot[1] as i32
                drop(snapshot)
                drop(empty)
                drop(root)
                drop(text)
                0
            }
            "#,
        );
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let string_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        let selection = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("payload-selection derivation")
            .expect("one persistent Set contributes the selected String type");
        assert_eq!(selection.selected_types.len(), 1);
        assert_eq!(selection.selected_types[0].type_id, string_type);
        assert!(selection
            .selected_types
            .iter()
            .all(|selected| selected.type_id != i32_type));

        let receipts = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("static OOB receipt reconstructs without a selected target type");
        let [receipt] = receipts.as_slice() else {
            panic!("one OOB Values unpack result receipt");
        };
        assert_eq!(receipt.result_type, i32_type);
        assert_eq!(
            receipt.index_disposition,
            crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::AlwaysOutOfBounds {
                raw_index: 1,
                snapshot_len: 1,
            }
        );
        assert!(receipt.validate_against_program(&program).is_ok());

        let owner = NodeId("function:main".into());
        let function = program.functions().get(&owner).expect("main MIR");
        let checker_cfg = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("embedded Checker CFG receipt");
        let [checker] = checker_cfg.values_unpack_receipts.as_slice() else {
            panic!("one embedded Checker OOB receipt");
        };
        assert_eq!(checker.index_disposition, receipt.index_disposition);
        assert!(checker.payload_selection.is_empty());
    }

    #[test]
    fn values_unpack_mir_rederives_the_payload_at_the_sorted_index() {
        let program = ordinary_map_v2_values_mixed_snapshot_program();
        let owner = NodeId("function:main".into());
        let function = program.functions().get(&owner).expect("main MIR").clone();
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let checker = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("private Checker Values receipt")
            .values_unpack_receipts[0]
            .clone();
        assert_eq!(checker.conversion_to, i32_type);
        let selection = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("payload-selection receipt")
            .expect("V2 Set lineage");
        let index = super::super::MirValueId::new(format!("expr:{}", checker.index_expression.0))
            .expect("literal index value");
        let mut forged = checker;
        forged.conversion_to =
            crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);

        assert!(
            ordinary_map_owned_any_v2_root_selects_payload_type(
                &function,
                &forged.source_local,
                &forged.conversion_to,
                &selection,
            ),
            "the same root contains a String Set, which is insufficient by itself"
        );
        assert!(
            ordinary_map_owned_any_v2_values_index_selects_payload_type(
                &function, &forged, &index, &selection,
            )
            .is_none(),
            "sorted index zero selects the i32 payload, so the String target must fail",
        );
    }

    #[test]
    fn values_index_replay_binds_the_winning_set_and_rejects_checker_or_mir_forgery() {
        let source = r#"
func main() -> i32 {
    let empty = map_new()
    let a = map_set(empty, "a", 41)
    let b = map_set(a, "b", 42)
    let without_b = map_remove(b, "b")
    let snapshot = values(without_b)
    let selected = snapshot[0] as i32
    drop(snapshot)
    drop(empty)
    drop(a)
    drop(b)
    drop(without_b)
    selected
}
"#;
        let program = ordinary_map_v2_unpack_program(source);
        let owner = NodeId("function:main".into());
        let original = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("Set/Remove Values receipt validates");
        let [receipt] = original.as_slice() else {
            panic!("one indexed Values unpack is receipted");
        };
        assert_eq!(
            receipt.index_disposition,
            crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::SelectedPayload
        );
        let function = program.functions().get(&owner).expect("main MIR");
        let checker_receipt = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("private Checker CFG receipt")
            .values_unpack_receipts
            .first()
            .expect("one Checker Values unpack");
        assert_eq!(checker_receipt.payload_selection.len(), 3);
        let removed_set = checker_receipt.payload_selection[1].clone();
        let winning_set = checker_receipt.payload_selection[2].clone();
        assert_ne!(removed_set, winning_set);
        let selection = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("payload-selection receipt")
            .expect("the source contains Map Set payloads");
        let (disposition, selected) = ordinary_map_owned_any_v2_values_index_selects_payload_type(
            function,
            checker_receipt,
            &receipt.index,
            &selection,
        )
        .expect("MIR replays the exact sorted live entry");
        assert_eq!(disposition, checker_receipt.index_disposition);
        assert_eq!(selected.as_ref().map(|(set, _)| set), Some(&winning_set));

        let mut forged_checker = program.clone();
        let mut function = program.functions().get(&owner).expect("main MIR").clone();
        let private_checker = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private Checker CFG receipt")
            .values_unpack_receipts
            .first_mut()
            .expect("one Checker Values unpack");
        private_checker.payload_selection.truncate(2);
        assert_eq!(
            private_checker.payload_selection.last(),
            Some(&removed_set),
            "the forged receipt ends at the same-type Set for b, even though Remove(b) made it absent"
        );
        assert_ne!(private_checker.payload_selection.last(), Some(&winning_set));
        forged_checker.replace_function_for_test_only(function);
        assert!(
            forged_checker
                .ordinary_map_owned_any_v2_values_unpack_result_receipts()
                .is_err(),
            "MIR replay must reject Checker lineage ending at the removed b Set"
        );

        let mut forged_mir = program.clone();
        let mut function = program.functions().get(&owner).expect("main MIR").clone();
        let b_digest = blake3::hash(b"b").to_hex().to_string();
        let (set_b_instruction, key_a) = {
            let instructions = function
                .blocks
                .values()
                .flat_map(|block| block.instructions.iter())
                .collect::<Vec<_>>();
            let key_a = instructions
                .iter()
                .find_map(|instruction| match &instruction.kind {
                    super::super::MirInstructionKind::Const {
                        result,
                        literal: crate::core::ir::ResolvedLiteral::String(value),
                    } if value.as_str() == "a" => Some(result.clone()),
                    _ => None,
                })
                .expect("MIR String literal for key a");
            let set_b = function
                .ownership
                .checker_ordinary_map_owned_any_v2
                .iter()
                .find(|action| {
                    action.kind == crate::core::OrdinaryMapOwnedAnyV2ActionKind::Set
                        && action.key_static_digest.as_deref() == Some(b_digest.as_str())
                })
                .expect("Checker MIR action for Set(b, 42)");
            (set_b.instruction.clone(), key_a)
        };
        let set_instruction = function
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| instruction.id == set_b_instruction)
            .expect("MIR Set(b, 42) instruction");
        let super::super::MirInstructionKind::OrdinaryMapOwnedAnyV2Set { key, .. } =
            &mut set_instruction.kind
        else {
            panic!("selected instruction is not a Map Set");
        };
        *key = key_a;
        forged_mir.replace_function_for_test_only(function);
        assert!(
            forged_mir
                .ordinary_map_owned_any_v2_values_unpack_result_receipts()
                .is_err(),
            "independent MIR replay must reject a Set whose key no longer matches its Checker identity"
        );
    }

    #[test]
    fn values_index_replay_rejects_same_type_set_overwritten_for_another_key() {
        let source = r#"
func main() -> i32 {
    let stale_a = "stale a payload"
    let live_b = "live b payload"
    let empty = map_new()
    let with_b = map_set(empty, "b", live_b)
    let with_stale_a = map_set(with_b, "a", stale_a)
    let current = map_set(with_stale_a, "a", 41)
    let snapshot = values(current)
    let selected = snapshot[1] as string
    drop(selected)
    drop(snapshot)
    drop(empty)
    drop(with_b)
    drop(with_stale_a)
    drop(current)
    drop(stale_a)
    drop(live_b)
    0
}
"#;
        let program = ordinary_map_v2_unpack_program(source);
        let owner = NodeId("function:main".into());
        let receipts = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("the sorted live String entry has an exact Values receipt");
        let [receipt] = receipts.as_slice() else {
            panic!("one indexed Values unpack is receipted");
        };
        assert_eq!(
            receipt.index_disposition,
            crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::SelectedPayload
        );
        let function = program.functions().get(&owner).expect("main MIR");
        let checker_receipt = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("private Checker CFG receipt")
            .values_unpack_receipts
            .first()
            .expect("one Checker Values unpack");
        let digest_a = blake3::hash(b"a").to_hex().to_string();
        let digest_b = blake3::hash(b"b").to_hex().to_string();
        let string_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let set_for = |digest: &str, value_type: &crate::core::ResolvedTypeId| {
            function
                .ownership
                .checker_ordinary_map_owned_any_v2
                .iter()
                .find(|action| {
                    action.kind == crate::core::OrdinaryMapOwnedAnyV2ActionKind::Set
                        && action.key_static_digest.as_deref() == Some(digest)
                        && action.value_type.as_ref() == Some(value_type)
                })
                .expect("exact persistent Set identity")
        };
        let set_b = set_for(&digest_b, &string_type);
        let stale_set_a = set_for(&digest_a, &string_type);
        let current_set_a = set_for(&digest_a, &i32_type);
        assert_eq!(
            checker_receipt.payload_selection,
            vec![
                current_set_a.point.clone(),
                stale_set_a.point.clone(),
                set_b.point.clone(),
            ],
            "index one must end at Set(b), not the overwritten same-type Set(a)"
        );

        let selection = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("payload-selection receipt")
            .expect("the source contains persistent Map Set payloads");
        let (disposition, selected_set) =
            ordinary_map_owned_any_v2_values_index_selects_payload_type(
                function,
                checker_receipt,
                &receipt.index,
                &selection,
            )
            .expect("MIR independently replays the live sorted entry");
        assert_eq!(disposition, checker_receipt.index_disposition);
        assert_eq!(
            selected_set,
            Some((set_b.point.clone(), set_b.instruction.clone())),
            "the MIR winner carries Set(b)'s exact source and instruction identity"
        );

        let mut forged = program.clone();
        let mut function = function.clone();
        function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private Checker CFG receipt")
            .values_unpack_receipts[0]
            .payload_selection = vec![current_set_a.point.clone(), stale_set_a.point.clone()];
        forged.replace_function_for_test_only(function);
        assert!(
            forged
                .ordinary_map_owned_any_v2_values_unpack_result_receipts()
                .is_err(),
            "MIR must reject a forged same-type lineage ending at overwritten Set(a)"
        );
    }

    #[test]
    fn ordinary_map_v2_values_label_field_move_carries_direct_string_reads() {
        use crate::core::OrdinaryMapOwnedAnyV2ValuesUnpackOwnerSettlementKind as OwnerSettlement;

        let program = ordinary_map_v2_unpack_program(include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_values_field_move.mimi"
        ));
        let receipts = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("direct field move and equality receipts validate");
        let [receipt] = receipts.as_slice() else {
            panic!("the fixture has exactly one Values unpack");
        };
        assert_eq!(
            receipt.result_owner_settlement,
            OwnerSettlement::DirectStringFieldMove
        );
        assert!(receipt.result_owner_whole_drop_unproved_uses.is_none());
        let field_move = receipt
            .result_owner_field_move
            .as_ref()
            .expect("the selected Label is consumed by its text projection");
        assert_eq!(field_move.source.field_name, "text");
        assert_eq!(field_move.source.text_read_uses.len(), 2);
        assert!(field_move.source.has_exact_source_use_sets());
        let [eq_read, ne_read] = field_move.source.text_read_uses.as_slice() else {
            panic!("Checker receipts one equality and one inequality read")
        };
        assert!(!eq_read.not_equal);
        assert_eq!(eq_read.peer_literal, "expected");
        assert!(ne_read.not_equal);
        assert_eq!(ne_read.peer_literal, "unexpected");
        for read in [eq_read, ne_read] {
            assert!(read.statement_order > field_move.source.text_binding_statement_order);
            assert!(read.statement_order < field_move.source.text_settlement_statement_order);
        }

        let [eq_mir_read, ne_mir_read] = field_move.text_read_uses.as_slice() else {
            panic!("MIR carries both direct String comparisons")
        };
        for (mir_read, source_read, expected_op) in [
            (
                eq_mir_read,
                eq_read,
                crate::core::ir::ResolvedBinaryOp::Equal,
            ),
            (
                ne_mir_read,
                ne_read,
                crate::core::ir::ResolvedBinaryOp::NotEqual,
            ),
        ] {
            assert_eq!(mir_read.source, *source_read);
            assert_eq!(
                mir_read.instruction.as_str(),
                format!("inst:binary:{}", source_read.operation.0)
            );
            assert_eq!(
                mir_read.result.as_str(),
                format!("expr:{}", source_read.operation.0)
            );
            assert_eq!(mir_read.op, expected_op);
            assert!(
                mir_read.left.as_str() == format!("local:{}", field_move.source.text_binding.0 .0)
                    || mir_read.right.as_str()
                        == format!("local:{}", field_move.source.text_binding.0 .0)
            );
        }
        receipt
            .validate_against_program(&program)
            .expect("source, MoveProject, direct Move, Eq/Ne operands, TypeDesc, and Drop agree");

        let function = program.functions().get(&receipt.owner).expect("main MIR");
        let block = function.blocks.get(&function.entry).expect("main entry");
        let projection_index = block
            .instructions
            .iter()
            .position(|instruction| instruction.id == field_move.projection_instruction)
            .expect("MoveProject");
        let text_binding_index = block
            .instructions
            .iter()
            .position(|instruction| instruction.id == field_move.text_binding_instruction)
            .expect("direct child Move");
        let eq_read_index = block
            .instructions
            .iter()
            .position(|instruction| instruction.id == eq_mir_read.instruction)
            .expect("direct equality Binary");
        let ne_read_index = block
            .instructions
            .iter()
            .position(|instruction| instruction.id == ne_mir_read.instruction)
            .expect("direct inequality Binary");
        let drop_index = block
            .instructions
            .iter()
            .position(|instruction| instruction.id == field_move.text_settlement_instruction)
            .expect("one explicit String Drop");
        assert!(projection_index < text_binding_index);
        assert!(text_binding_index < eq_read_index);
        assert!(eq_read_index < ne_read_index);
        assert!(ne_read_index < drop_index);
    }

    #[test]
    fn ordinary_map_v2_values_label_source_use_commitment_survives_erased_alias_lowering() {
        let (checked, functions, catalog) =
            super::super::test_support::ordinary_map_values_label_erased_alias_fixture();
        let owner = NodeId("function:main".into());
        let body = checked.resolved_body(&owner).expect("checked main body");
        let alias_local = body
            .locals
            .values()
            .find(|local| local.display_name == "alias")
            .expect("alias source local");
        let alias_loads = body
            .root
            .statements
            .iter()
            .filter_map(|statement| {
                let crate::core::ir::ResolvedStmtKind::Bind {
                    pattern,
                    initializer: Some(initializer),
                } = &statement.kind
                else {
                    return None;
                };
                if !matches!(
                    &pattern.kind,
                    crate::core::ir::ResolvedPatternKind::Binding { local, by_reference: None }
                        if local == &alias_local.id
                ) || !matches!(
                    &initializer.kind,
                    crate::core::ir::ResolvedExprKind::Load(place)
                        if place.projections.is_empty()
                ) {
                    return None;
                }
                Some(initializer.node_id.clone())
            })
            .collect::<Vec<_>>();
        let [alias_load] = alias_loads.as_slice() else {
            panic!("the fixture has exactly one direct alias Load, got {alias_loads:?}");
        };
        let function = functions.get(&owner).expect("main MIR");
        let source_uses = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("private Checker source receipt")
            .values_unpack_receipts[0]
            .result_owner_whole_drop_unproved_uses
            .as_ref()
            .expect("source-use commitment");
        assert!(
            !source_uses.is_empty(),
            "the actual source has an alias Load"
        );
        assert_eq!(
            source_uses,
            &std::collections::BTreeSet::from([alias_load.clone()]),
            "the Checker commitment transferred to MIR is the exact source alias Load"
        );
        // The fixture reseals the erased MIR exactly as a lowering bug before
        // full-body sealing would. The source census remains independent.
        let mut counterfactual = functions.clone();
        let error = MirProgram::with_type_catalog(functions, catalog.clone())
            .expect_err("erasing unsupported source uses cannot mint an isolated-owner receipt");
        assert!(
            error
                .iter()
                .any(|error| error.message.contains("source-use commitment")),
            "{error:?}"
        );

        // Test-only removal of the independent source commitment recreates the
        // old acceptance condition and proves this guard is not a duplicate of
        // the existing exact-MIR-Drop check.
        let checker = counterfactual
            .get_mut(&owner)
            .expect("main MIR")
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("source receipt");
        checker.values_unpack_receipts[0].result_owner_whole_drop_unproved_uses =
            Some(Default::default());
        MirProgram::with_type_catalog(counterfactual, catalog)
            .expect("the erased MIR alone satisfies the existing isolated whole-Drop contract");
    }

    #[test]
    fn ordinary_map_v2_values_label_source_use_commitment_is_rechecked_by_every_consumer() {
        let original = ordinary_map_v2_unpack_program(
            r#"
type Label { text: string }
func main() -> i32 {
    let label = Label { text: "isolated owner" }
    let empty = map_new()
    let root = map_set(empty, "label", label)
    let snapshot = values(root)
    let item = snapshot[0] as Label
    drop(item)
    drop(snapshot)
    drop(root)
    drop(empty)
    drop(label)
    0
}
"#,
        );
        let receipts = original
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("isolated Label receipt");
        assert_eq!(receipts.len(), 1);
        let receipt = receipts.into_iter().next().expect("one Label receipt");
        assert_eq!(
            receipt.schema,
            "mimi-ordinary-map-owned-any-v2-values-unpack-result-v3"
        );
        assert_eq!(
            receipt.result_owner_whole_drop_unproved_uses,
            Some(Default::default())
        );
        let mut legacy_schema = receipt.clone();
        legacy_schema.schema = "mimi-ordinary-map-owned-any-v2-values-unpack-result-v1";
        assert!(
            legacy_schema.validate().is_err(),
            "v1 does not attest source-use closure"
        );
        for source_uses in [
            None,
            Some(std::collections::BTreeSet::from([NodeId(
                "forged:source-alias-load".into(),
            )])),
        ] {
            let mut program = original.clone();
            let mut function = program
                .functions()
                .get(&receipt.owner)
                .expect("main MIR")
                .clone();
            function
                .ownership
                .checker_ordinary_map_owned_any_v2_cfg_receipt
                .as_mut()
                .expect("private source receipt")
                .values_unpack_receipts[0]
                .result_owner_whole_drop_unproved_uses = source_uses;
            program.replace_function_for_test_only(function);
            assert_ne!(
                program.route_receipt("test").ownership_digest,
                original.route_receipt("test").ownership_digest
            );
            let error = program
                .ordinary_map_owned_any_v2_values_unpack_result_receipts()
                .expect_err("Core requires the complete source-use commitment");
            assert!(error.contains("source-use commitment"), "{error}");
            let interpreter = super::super::reference::MirReferenceInterpreter::new(&program);
            let error = interpreter
                .execute(&receipt.owner, &[])
                .expect_err("reference execution rejects before opening its execution domain");
            assert!(
                error.to_string().contains("source-use commitment"),
                "{error}"
            );
            assert!(interpreter.captured_output().is_empty());
            let errors = crate::interp::bytecode::compile_mir_program(&program)
                .expect_err("bytecode adapter revalidates before emission");
            assert!(
                errors
                    .iter()
                    .any(|error| error.message.contains("source-use commitment")),
                "{errors:?}"
            );
            let errors = crate::codegen::mir::validate_mir_native(&program)
                .expect_err("native preflight revalidates before emission");
            assert!(
                errors
                    .iter()
                    .any(|error| error.message.contains("source-use commitment")),
                "{errors:?}"
            );
            let errors = crate::verifier::validate_mir_capabilities(&program)
                .expect_err("verifier capability gate revalidates the source commitment");
            assert!(
                errors
                    .iter()
                    .any(|error| error.contains("source-use commitment")),
                "{errors:?}"
            );
        }
    }

    #[test]
    fn ordinary_map_v2_values_unpack_receipt_separates_result_owner_drops_from_snapshot_drop() {
        use crate::core::OrdinaryMapOwnedAnyV2ValuesUnpackOwnerSettlementKind as OwnerSettlement;

        let source = r#"
type Label { text: string }
func main() -> i32 {
    let label = Label { text: "owner receipt Label" }
    let empty = map_new()
    let with_label = map_set(empty, "z", label)
    let with_number = map_set(with_label, "a", 42)
    let both = map_set(with_number, "m", "owner receipt String")
    let snapshot = values(both)
    let number = snapshot[0] as i32
    let text = snapshot[1] as string
    let label_copy = snapshot[2] as Label
    drop(snapshot)
    drop(number)
    drop(label_copy)
    drop(empty)
    drop(with_label)
    drop(with_number)
    drop(both)
    drop(label)
    0
}
"#;
        let mut program = ordinary_map_v2_unpack_program(source);
        let receipts = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect("i32, String, and whole-Label result owners have exact receipts");
        assert_eq!(receipts.len(), 3);
        let i32_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        let string_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
        let number = receipts
            .iter()
            .find(|receipt| receipt.result_type == i32_type)
            .expect("Copy result receipt");
        assert_eq!(
            number.result_owner_settlement,
            OwnerSettlement::NoOwnedPayload
        );
        assert!(number.result_owner_settlement_instruction.is_none());

        let text = receipts
            .iter()
            .find(|receipt| receipt.result_type == string_type)
            .expect("String result receipt");
        assert_eq!(
            text.result_owner_settlement,
            OwnerSettlement::CompilerOwnedStringDrop
        );
        let text_anchor = text
            .result_owner_settlement_point
            .as_ref()
            .expect("root tail-expression cleanup anchor");
        let text_drop = text
            .result_owner_settlement_instruction
            .as_ref()
            .expect("exact String binding cleanup instruction");
        assert!(text_drop.as_str().ends_with(&format!(":{}", text_anchor.0)));
        assert!(program
            .functions()
            .get(&text.owner)
            .expect("String owner function")
            .blocks
            .values()
            .flat_map(|block| &block.instructions)
            .any(|instruction| {
                &instruction.id == text_drop
                    && matches!(
                        &instruction.kind,
                        super::super::MirInstructionKind::Drop { value }
                            if value == &text.result_binding
                    )
            }));

        let label = receipts
            .iter()
            .find(|receipt| receipt.result_type != i32_type && receipt.result_type != string_type)
            .expect("Label result receipt");
        assert_eq!(
            label.result_owner_settlement,
            OwnerSettlement::ExplicitWholeDrop
        );
        let label_drop = label
            .result_owner_settlement_instruction
            .as_ref()
            .expect("exact Label whole-Drop instruction");
        let function = program
            .functions()
            .get(&label.owner)
            .expect("Label owner function");
        assert!(function
            .blocks
            .values()
            .flat_map(|block| &block.instructions)
            .any(|instruction| {
                &instruction.id == label_drop
                    && matches!(
                        &instruction.kind,
                        super::super::MirInstructionKind::Drop { value }
                            if value == &label.result_binding
                    )
            }));
        assert!(label.result_owner_settlement_point.is_some());
        assert!(label.result_owner_settlement_index.is_some());
        assert_eq!(
            label.settlement_instruction, receipts[0].settlement_instruction,
            "the Values snapshot Drop remains a separate shared receipt"
        );

        let mut forged = program
            .functions()
            .get(&label.owner)
            .expect("Label owner function")
            .clone();
        let forged_drop = forged
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| &instruction.id == label_drop)
            .expect("Label owner Drop instruction");
        forged_drop.id = super::super::MirInstructionId::new("inst:drop:forged-label-owner")
            .expect("forged instruction id");
        program.replace_function_for_test_only(forged);
        let error = program
            .ordinary_map_owned_any_v2_values_unpack_result_receipts()
            .expect_err("the Label owner Drop must retain its exact Checker statement/place ID");
        assert!(error.contains("exact Checker point/index"), "{error}");
    }

    #[test]
    fn ordinary_map_v2_temporary_root_receipt_binds_new_get_any_and_immediate_drop() {
        let program = ordinary_map_v2_temporary_root_program();
        let receipts = program
            .ordinary_map_owned_any_v2_get_any_result_receipts()
            .expect("temporary-root GetAny receipt validates");
        let [receipt] = receipts.as_slice() else {
            panic!("one temporary-root GetAny result receipt is expected");
        };
        let root = receipt
            .temporary_root
            .as_ref()
            .expect("immediate map_new source is bound into the shared receipt");
        assert_eq!(root.local, receipt.source_local);
        assert_eq!(root.root, receipt.root);
        assert_eq!(root.source_node, receipt.source_node);
        assert_eq!(root.get_any, receipt.operation);
        assert_eq!(root.get_any_instruction, receipt.instruction);
        assert_eq!(root.settlement_point, receipt.operation);

        let function = program
            .functions()
            .values()
            .find(|function| {
                function
                    .ownership
                    .checker_ordinary_map_owned_any_v2_cfg_receipt
                    .as_ref()
                    .is_some_and(|cfg| !cfg.temporary_root_receipts.is_empty())
            })
            .expect("temporary-root GetAny function");
        let action = function
            .ownership
            .checker_ordinary_map_owned_any_v2
            .iter()
            .find(|action| action.kind == crate::core::OrdinaryMapOwnedAnyV2ActionKind::GetAny)
            .expect("source-backed temporary-root GetAny action");
        let cfg = function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("temporary-root Checker CFG receipt");
        let checker_action = cfg
            .actions
            .iter()
            .find(|candidate| candidate.point == action.point && candidate.kind == action.kind)
            .expect("matching Checker GetAny action");
        let operation = function
            .blocks
            .values()
            .flat_map(|block| &block.instructions)
            .find(|instruction| instruction.id == receipt.instruction)
            .expect("MIR GetAny instruction");
        let interposed_drop =
            super::super::checker_receipted_ordinary_map_owned_any_v2_temporary_root_drop(
                function,
                action,
                Some(checker_action),
                operation,
            )
            .expect("only the exact temporary-root Checker receipt authorizes the root Drop");
        let crate::core::mir::MirInstructionKind::OrdinaryMapOwnedAnyV2GetAny { key, .. } =
            &operation.kind
        else {
            panic!("the receipt instruction is GetAny");
        };
        let key_operands = vec![key.clone()];
        assert!(
            super::super::validate_ordinary_map_string_argument_lifetimes_with_interposed_drop(
                function,
                &operation.id,
                &key_operands,
                None,
                Some(&interposed_drop),
            ),
            "the exact immediate root Drop may precede the unique literal-key Drop"
        );

        let mut wrong_key_drop = function.clone();
        let key_drop = wrong_key_drop
            .blocks
            .values_mut()
            .find_map(|block| {
                let get_any_index = block
                    .instructions
                    .iter()
                    .position(|instruction| instruction.id == operation.id)?;
                block.instructions.get_mut(get_any_index + 2)
            })
            .expect("the literal-key Drop follows the immediate root Drop");
        let crate::core::mir::MirInstructionKind::Drop { value } = &mut key_drop.kind else {
            panic!("the third instruction is the owned key Drop");
        };
        *value = crate::core::mir::MirValueId::new("forged:temporary-key-drop")
            .expect("forged value identity is valid for the negative test");
        assert!(
            !super::super::validate_ordinary_map_string_argument_lifetimes_with_interposed_drop(
                &wrong_key_drop,
                &operation.id,
                &key_operands,
                None,
                Some(&interposed_drop),
            ),
            "the root-drop exception does not waive the exact owned-key Drop"
        );

        let mut missing_source_receipt = function.clone();
        missing_source_receipt
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("temporary-root Checker CFG receipt")
            .temporary_root_receipts
            .clear();
        let missing_cfg = missing_source_receipt
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("temporary-root Checker CFG receipt remains present");
        let missing_checker_action = missing_cfg
            .actions
            .iter()
            .find(|candidate| candidate.point == action.point && candidate.kind == action.kind)
            .expect("GetAny action remains source-backed");
        assert!(
            super::super::checker_receipted_ordinary_map_owned_any_v2_temporary_root_drop(
                &missing_source_receipt,
                action,
                Some(missing_checker_action),
                operation,
            )
            .is_none(),
            "a neighboring MIR root Drop without the source receipt grants no exception"
        );
        assert!(
            !super::super::validate_ordinary_map_string_argument_lifetimes(
                &missing_source_receipt,
                &operation.id,
                &key_operands,
                None,
            ),
            "the ordinary lifetime rule still rejects a key Drop separated by an unreceipted root Drop"
        );

        let mut forged_source_receipt = function.clone();
        forged_source_receipt
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("temporary-root Checker CFG receipt")
            .temporary_root_receipts[0]
            .source_node = crate::core::NodeId("forged-temporary-root-source".into());
        let forged_cfg = forged_source_receipt
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("forged Checker CFG receipt remains present");
        let forged_checker_action = forged_cfg
            .actions
            .iter()
            .find(|candidate| candidate.point == action.point && candidate.kind == action.kind)
            .expect("GetAny action remains source-backed");
        assert!(
            super::super::checker_receipted_ordinary_map_owned_any_v2_temporary_root_drop(
                &forged_source_receipt,
                action,
                Some(forged_checker_action),
                operation,
            )
            .is_none(),
            "a mismatched temporary-root source identity grants no exception"
        );

        let mut missing = program.clone();
        let mut function = program
            .functions()
            .values()
            .find(|function| {
                function
                    .ownership
                    .checker_ordinary_map_owned_any_v2_cfg_receipt
                    .as_ref()
                    .is_some_and(|cfg| !cfg.temporary_root_receipts.is_empty())
            })
            .expect("temporary-root GetAny function")
            .clone();
        function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("temporary-root Checker CFG receipt")
            .temporary_root_receipts
            .clear();
        missing.replace_function_for_test_only(function);
        assert!(
            missing
                .ordinary_map_owned_any_v2_get_any_result_receipts()
                .is_err(),
            "a missing temporary-root Checker receipt cannot be reconstructed from MIR"
        );

        let mut tampered = program.clone();
        let mut function = program
            .functions()
            .values()
            .find(|function| {
                function
                    .ownership
                    .checker_ordinary_map_owned_any_v2_cfg_receipt
                    .as_ref()
                    .is_some_and(|cfg| !cfg.temporary_root_receipts.is_empty())
            })
            .expect("temporary-root GetAny function")
            .clone();
        function
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("temporary-root Checker CFG receipt")
            .temporary_root_receipts[0]
            .source_type = crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32);
        tampered.replace_function_for_test_only(function);
        assert!(
            tampered
                .ordinary_map_owned_any_v2_get_any_result_receipts()
                .is_err(),
            "a temporary-root source TypeId mutation invalidates the shared MIR receipt"
        );
    }

    #[test]
    fn ordinary_map_v2_payload_selection_rejects_missing_extra_and_forged_rows() {
        let program = ordinary_map_v2_program();
        let receipt = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("selection derives")
            .expect("V2 Set actions produce a selection");

        let mut missing = receipt.clone();
        missing.entries.pop();
        assert!(
            missing.validate().is_err(),
            "missing Checker Set row is rejected"
        );
        assert!(missing.validate_against_program(&program).is_err());

        let mut extra = receipt.clone();
        extra.entries.push(receipt.entries[0].clone());
        assert!(
            extra.validate().is_err(),
            "duplicate/extra Set row is rejected"
        );

        let mut forged = receipt.clone();
        forged.entries[0].value =
            super::super::MirValueId::new("forged:payload").expect("test value identity is valid");
        assert!(
            forged.validate().is_err(),
            "forged MIR value invalidates the digest"
        );
        assert!(forged.validate_against_program(&program).is_err());

        let mut forged_type = receipt.clone();
        forged_type.selected_types[0].type_id = forged_type.entries[0].checker_type.clone();
        forged_type.selected_types[0].type_desc_digest = "0".repeat(64);
        assert!(
            forged_type.validate().is_err(),
            "forged TypeDesc digest is rejected"
        );
    }

    #[test]
    fn ordinary_map_v2_payload_selection_rejects_unreceipted_or_changed_mir_sets() {
        use crate::core::mir::MirInstructionKind as Instruction;

        let program = ordinary_map_v2_program();
        let mut missing_action = program.clone();
        let mut function = program
            .functions()
            .values()
            .find(|function| {
                function
                    .blocks
                    .values()
                    .flat_map(|block| &block.instructions)
                    .any(|instruction| {
                        matches!(
                            instruction.kind,
                            Instruction::OrdinaryMapOwnedAnyV2Set { .. }
                        )
                    })
            })
            .expect("V2 Set function")
            .clone();
        function
            .ownership
            .checker_ordinary_map_owned_any_v2
            .retain(|action| action.kind != crate::core::OrdinaryMapOwnedAnyV2ActionKind::Set);
        missing_action.replace_function_for_test_only(function);
        assert!(
            missing_action
                .ordinary_map_owned_any_v2_payload_selection_receipt()
                .is_err(),
            "an MIR Set cannot authorize its own payload descriptor"
        );

        let mut changed_mir = program.clone();
        let mut function = program
            .functions()
            .values()
            .find(|function| {
                function
                    .blocks
                    .values()
                    .flat_map(|block| &block.instructions)
                    .any(|instruction| {
                        matches!(
                            instruction.kind,
                            Instruction::OrdinaryMapOwnedAnyV2Set { .. }
                        )
                    })
            })
            .expect("V2 Set function")
            .clone();
        let set = function
            .blocks
            .values_mut()
            .flat_map(|block| &mut block.instructions)
            .find(|instruction| {
                matches!(
                    instruction.kind,
                    Instruction::OrdinaryMapOwnedAnyV2Set { .. }
                )
            })
            .expect("V2 Set instruction");
        let replacement = function
            .values
            .keys()
            .find(|value| match &set.kind {
                Instruction::OrdinaryMapOwnedAnyV2Set {
                    value: original, ..
                } => *value != original,
                _ => false,
            })
            .expect("another MIR value")
            .clone();
        let Instruction::OrdinaryMapOwnedAnyV2Set { value, .. } = &mut set.kind else {
            unreachable!()
        };
        *value = replacement;
        changed_mir.replace_function_for_test_only(function);
        assert!(
            changed_mir
                .ordinary_map_owned_any_v2_payload_selection_receipt()
                .is_err(),
            "a Set operand changed after Checker lowering cannot mint a receipt"
        );
    }

    #[test]
    fn ordinary_map_v2_payload_selection_binds_the_type_catalog_digest() {
        let program = ordinary_map_v2_program();
        let receipt = program
            .ordinary_map_owned_any_v2_payload_selection_receipt()
            .expect("selection derives")
            .expect("V2 Set actions produce a selection");

        let mut catalog = program.type_catalog().clone();
        let (primitive_id, primitive) = catalog
            .iter()
            .find(|(id, descriptor)| {
                !receipt
                    .selected_types
                    .iter()
                    .any(|selected| &selected.type_id == *id)
                    && matches!(
                        descriptor.kind,
                        crate::core::mir::types::MirTypeKind::Primitive(_)
                    )
            })
            .map(|(id, descriptor)| (id.clone(), descriptor.clone()))
            .expect("fixture has an unselected primitive TypeDesc");
        let extra_id = crate::core::ir::ResolvedTypeId::synthetic(
            "mimi-test:ordinary-map-owned-any-v2-extra-type",
        );
        let mut extra_descriptor = primitive;
        extra_descriptor.id = extra_id.clone();
        catalog.replace_for_test_only(extra_id, extra_descriptor);
        let changed_catalog_program =
            MirProgram::with_type_catalog(program.functions().clone(), catalog)
                .expect("an unused additional TypeDesc keeps function MIR valid");

        assert!(
            receipt
                .validate_against_program(&changed_catalog_program)
                .is_err(),
            "the selection is bound to the complete TypeDesc catalog digest"
        );
        assert!(program.type_catalog().get(&primitive_id).is_some());
    }

