    #[test]
    fn values_mixed_snapshot_remove_receipt_binds_update_and_every_owner_drop() {
        let original = ordinary_map_v2_values_mixed_snapshot_remove_program();
        let receipts = original
            .ordinary_map_owned_any_v2_values_mixed_snapshot_remove_receipts()
            .expect("exact Checker/MIR snapshot-Remove witness derives");
        let [receipt] = receipts.as_slice() else {
            panic!("fixture has one independent snapshot-Remove witness");
        };
        assert_eq!(
            receipt.checker.remove_key_bytes, b"b-text",
            "Remove is bound to the key represented by snapshot entry 1"
        );
        assert_eq!(receipt.snapshot.entries.len(), 3);
        assert_eq!(receipt.snapshot.map_root_settlements.len(), 4);
        receipt
            .validate_against_program(&original)
            .expect("receipt rederives from Checker and canonical MIR");
        crate::core::mir::validate_ordinary_map_owned_any_v2_values_mixed_snapshot_remove_mir_route(
            &original,
        )
        .expect("strict MIR-only route validates without broad readiness");

        let owner = receipt.owner.clone();
        let mut changed_key = original.clone();
        let mut main = changed_key
            .functions()
            .get(&owner)
            .expect("main MIR")
            .clone();
        main.ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private V2 Checker CFG receipt")
            .values_mixed_snapshot_remove_receipts[0]
            .remove_key_bytes = b"a-number".to_vec();
        changed_key.replace_function_for_test_only(main);
        assert!(changed_key
            .ordinary_map_owned_any_v2_values_mixed_snapshot_remove_receipts()
            .is_err());

        let mut missing_removed_root_drop = original.clone();
        let mut main = missing_removed_root_drop
            .functions()
            .get(&owner)
            .expect("main MIR")
            .clone();
        let drop_instruction = receipt.removed_root_settlement.instruction.clone();
        let entry = main.entry.clone();
        main.blocks
            .get_mut(&entry)
            .expect("main entry block")
            .instructions
            .retain(|instruction| instruction.id != drop_instruction);
        missing_removed_root_drop.replace_function_for_test_only(main);
        assert!(missing_removed_root_drop
            .ordinary_map_owned_any_v2_values_mixed_snapshot_remove_receipts()
            .is_err());
        assert!(crate::core::mir::validate_ordinary_map_owned_any_v2_values_mixed_snapshot_remove_mir_route(
            &missing_removed_root_drop,
        )
        .is_err());

        let mut remove_before_values = original.clone();
        let mut main = remove_before_values
            .functions()
            .get(&owner)
            .expect("main MIR")
            .clone();
        let entry = main.entry.clone();
        let instructions = &mut main
            .blocks
            .get_mut(&entry)
            .expect("main entry block")
            .instructions;
        let remove_index = instructions
            .iter()
            .position(|instruction| instruction.id == receipt.remove_instruction)
            .expect("Remove instruction");
        let values_index = instructions
            .iter()
            .position(|instruction| instruction.id == receipt.snapshot.values.instruction)
            .expect("Values instruction");
        let remove = instructions.remove(remove_index);
        instructions.insert(values_index, remove);
        remove_before_values.replace_function_for_test_only(main);
        assert!(remove_before_values
            .ordinary_map_owned_any_v2_values_mixed_snapshot_remove_receipts()
            .is_err());
    }

    #[test]
    fn values_snapshot_replacement_receipt_is_checker_anchored_and_rejects_forgery() {
        let original = ordinary_map_v2_values_snapshot_replacement_program();
        let receipts = original
            .ordinary_map_owned_any_v2_values_snapshot_replacement_receipts()
            .expect("exact Checker/MIR snapshot-replacement receipt derives");
        let [receipt] = receipts.as_slice() else {
            panic!("fixture has one independent snapshot-replacement witness");
        };
        assert_eq!(receipt.entries[0].checker.index, 0);
        assert_eq!(receipt.entries[1].checker.index, 1);
        assert!(receipt.entries[0].checker.key_bytes < receipt.entries[1].checker.key_bytes);
        let checker_cfg = original
            .functions()
            .get(&receipt.owner)
            .expect("main MIR")
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("embedded private Checker CFG receipt");
        assert_eq!(checker_cfg.values_unpack_receipts.len(), 2);
        for entry in &receipt.entries {
            let matching = checker_cfg
                .values_unpack_receipts
                .iter()
                .filter(|unpack| unpack.cast == entry.checker.cast)
                .collect::<Vec<_>>();
            let [unpack] = matching.as_slice() else {
                panic!("snapshot entry has one exact Checker Values unpack");
            };
            assert_eq!(
                unpack.index_disposition,
                crate::core::OrdinaryMapOwnedAnyV2ValuesIndexDisposition::SelectedPayload
            );
            assert_eq!(
                unpack.payload_selection.last(),
                Some(&entry.checker.set_point),
                "the complete lineage ends at this sorted index's winning Set"
            );
        }
        assert_eq!(
            checker_cfg
                .values_unpack_receipts
                .iter()
                .find(|unpack| unpack.cast == receipt.entries[0].checker.cast)
                .expect("index-zero Checker unpack")
                .payload_selection,
            vec![
                receipt.entries[1].checker.set_point.clone(),
                receipt.entries[0].checker.set_point.clone(),
            ],
            "index zero follows the newer same-type b Set and terminates at the earlier a Set"
        );
        assert_eq!(
            checker_cfg
                .values_unpack_receipts
                .iter()
                .find(|unpack| unpack.cast == receipt.entries[1].checker.cast)
                .expect("index-one Checker unpack")
                .payload_selection,
            vec![receipt.entries[1].checker.set_point.clone()],
            "index one terminates at the later b Set"
        );
        receipt
            .validate_against_program(&original)
            .expect("receipt rederives from the embedded Checker CFG authority");

        let owner = receipt.owner.clone();
        let mut missing_checker = original.clone();
        let mut main = missing_checker
            .functions()
            .get(&owner)
            .expect("main MIR")
            .clone();
        main.ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private V2 Checker CFG receipt")
            .values_snapshot_replacement_receipts
            .clear();
        missing_checker.replace_function_for_test_only(main);
        assert!(missing_checker
            .ordinary_map_owned_any_v2_values_snapshot_replacement_receipts()
            .expect("absence is not promoted to an MIR-derived witness")
            .is_empty());
        assert!(crate::core::mir::validate_ordinary_map_owned_any_v2_values_snapshot_replacement_mir_route(
            &missing_checker
        )
        .is_err());

        let mut confused_payload = original.clone();
        let mut main = confused_payload
            .functions()
            .get(&owner)
            .expect("main MIR")
            .clone();
        let checker = main
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private V2 Checker CFG receipt")
            .values_snapshot_replacement_receipts
            .first_mut()
            .expect("snapshot-replacement Checker receipt");
        checker.replacement.payload_node = checker.entries[0].payload_node.clone();
        checker.replacement.payload_text = checker.entries[0].payload_text.clone();
        confused_payload.replace_function_for_test_only(main);
        assert!(confused_payload
            .ordinary_map_owned_any_v2_values_snapshot_replacement_receipts()
            .is_err());

        let mut exchanged_indices = original.clone();
        let mut main = exchanged_indices
            .functions()
            .get(&owner)
            .expect("main MIR")
            .clone();
        let entries = &mut main
            .ownership
            .checker_ordinary_map_owned_any_v2_cfg_receipt
            .as_mut()
            .expect("private V2 Checker CFG receipt")
            .values_snapshot_replacement_receipts[0]
            .entries;
        entries[0].index = 1;
        entries[1].index = 0;
        exchanged_indices.replace_function_for_test_only(main);
        assert!(exchanged_indices
            .ordinary_map_owned_any_v2_values_snapshot_replacement_receipts()
            .is_err());

        let mut missing_root_drop = original.clone();
        let mut main = missing_root_drop
            .functions()
            .get(&owner)
            .expect("main MIR")
            .clone();
        let root_drop = receipt.map_root_settlements[0].instruction.clone();
        let entry = main.entry.clone();
        main.blocks
            .get_mut(&entry)
            .expect("main entry block")
            .instructions
            .retain(|instruction| instruction.id != root_drop);
        missing_root_drop.replace_function_for_test_only(main);
        assert!(missing_root_drop
            .ordinary_map_owned_any_v2_values_snapshot_replacement_receipts()
            .is_err());
    }

    #[test]
    fn values_producer_caller_receipt_binds_surface_and_dedicated_owner_types() {
        let program = values_producer_caller_program();
        let receipts = program
            .ordinary_map_owned_any_v2_values_producer_caller_receipts()
            .expect("exact bridge derives");
        let [receipt] = receipts.as_slice() else {
            panic!("one direct producer-caller bridge")
        };
        let values_type = super::super::types::ordinary_map_owned_any_v2_values_type_id();
        assert_eq!(receipt.producer_result_type, values_type);
        assert_eq!(receipt.call_result_type, values_type);
        assert_eq!(receipt.owner_type, values_type);
        assert_eq!(
            receipt.producer_checker_snapshot_type,
            receipt.checker_producer.snapshot_type
        );
        assert_eq!(
            receipt.producer_surface_return_type,
            receipt.checker_producer.surface_return_type
        );
        assert_eq!(
            receipt.call_surface_result_type,
            receipt.checker_caller.result_type
        );
        assert_eq!(
            receipt.producer_surface_return_type,
            receipt.call_surface_result_type
        );
        assert_ne!(
            receipt.producer_checker_snapshot_type,
            receipt.producer_surface_return_type
        );
        assert_eq!(
            receipt.producer_return_conversion_kind,
            crate::core::ir::CheckedConversionKind::ContainerErase
        );
        assert_eq!(receipt.len_receiver_type.as_ref(), Some(&values_type));
        let len_receiver = receipt.len_receiver.as_ref().expect("Len receiver receipt");
        assert_eq!(
            program
                .functions()
                .get(&receipt.caller_owner)
                .expect("caller MIR")
                .values
                .get(len_receiver)
                .map(|value| &value.ty),
            Some(&values_type)
        );
        receipt
            .validate_against_program(&program)
            .expect("source erasure, MIR owner and caller binding agree");
    }

